  const [selectedTooth, setSelectedTooth] = useState<string | null>(null);
  const [addConditionOpen, setAddConditionOpen] = useState(false);
  const [formData, setFormData] = useState({ condition_type: 'caries', surface: '', status: 'existing', severity: '', notes: '' });

  // Fetch Chart Data
  const { data: chartData, isLoading } = useQuery({
    queryKey: ['dental-chart', patientId],
    queryFn: () => clinicalApi.getPatientChart(patientId),
  });

  const { data: historyData } = useQuery({
    queryKey: ['dental-chart-history', patientId],
    queryFn: () => clinicalApi.getChartHistory(patientId),
  });

  const addMut = useMutation({
    mutationFn: (data: Partial<ToothCondition>) => clinicalApi.addCondition(patientId, data),
    onSuccess: () => {
      toast({ title: 'Condition added successfully' });
      setAddConditionOpen(false);
      queryClient.invalidateQueries({ queryKey: ['dental-chart', patientId] });
      queryClient.invalidateQueries({ queryKey: ['dental-chart-history', patientId] });
      setFormData({ condition_type: 'caries', surface: '', status: 'existing', severity: '', notes: '' });
    }
  });

  const removeMut = useMutation({
    mutationFn: (id: string) => clinicalApi.removeCondition(patientId, id),
    onSuccess: () => {
      toast({ title: 'Condition removed' });
      queryClient.invalidateQueries({ queryKey: ['dental-chart', patientId] });
    }
  });

  const conditions = chartData?.conditions || [];
  const history = historyData?.history || [];

  const getConditionsForTooth = (t: string) => conditions.filter(c => c.tooth_number === t);

  // SVG representation of a single tooth
  const renderToothSVG = (toothNum: string, isUpper: boolean) => {
    const toothConditions = getConditionsForTooth(toothNum);
    const isSelected = selectedTooth === toothNum;

    // Check for missing
    const isMissing = toothConditions.some(c => c.condition_type === 'missing');

    // Generate fill colors based on conditions (simplified representation)
    const baseColor = isMissing ? '#f1f5f9' : '#ffffff';
    let overlayColor = 'transparent';
    let hasStroke = false;
    let strokeColor = '#cbd5e1';

    if (!isMissing && toothConditions.length > 0) {
      // Find highest priority condition to show
      const priority = toothConditions[0];
      overlayColor = CONDITION_COLORS[priority.condition_type] || 'transparent';
      hasStroke = true;
      strokeColor = overlayColor;
    }

    return (
      <div 
        key={toothNum} 
        className={`flex flex-col items-center cursor-pointer transition-all ${isSelected ? 'scale-110 z-10' : 'hover:scale-105'}`}
        onClick={() => setSelectedTooth(toothNum)}
      >
        <div className={`text-xs font-semibold mb-1 ${isSelected ? 'text-blue-600' : 'text-slate-500'}`}>{toothNum}</div>
        <svg width="40" height="50" viewBox="0 0 40 50" className={`filter drop-shadow-sm ${isSelected ? 'ring-2 ring-blue-500 rounded-sm' : ''}`}>
          {/* Simple tooth shape representation */}
          <path 
            d={isUpper ? "M10 40 Q20 50 30 40 L35 10 Q20 0 5 10 Z" : "M10 10 Q20 0 30 10 L35 40 Q20 50 5 40 Z"}
            fill={baseColor}
            stroke={hasStroke ? strokeColor : "#cbd5e1"}
            strokeWidth={isSelected ? "2" : "1"}
          />

          {/* Condition Overlays */}
          {!isMissing && toothConditions.map((c, i) => {
            const color = CONDITION_COLORS[c.condition_type] || '#000';
            // Render surface indicators
            if (c.surface?.includes('O')) return <circle key={i} cx="20" cy="25" r="5" fill={color} opacity="0.8"/>;
            if (c.surface?.includes('M')) return <rect key={i} x="5" y="20" width="8" height="10" fill={color} opacity="0.8"/>;
            if (c.surface?.includes('D')) return <rect key={i} x="27" y="20" width="8" height="10" fill={color} opacity="0.8"/>;
            // Default center blob
            return <circle key={i} cx="20" cy="25" r="8" fill={color} opacity="0.5"/>;
          })}

          {isMissing && (
            <line x1="5" y1="5" x2="35" y2="45" stroke="#94a3b8" strokeWidth="2" />
          )}
        </svg>
      </div>
    );
  };

  const handleAddSubmit = () => {
    if (!selectedTooth) return;
    addMut.mutate({
      tooth_number: selectedTooth,
      ...formData
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex gap-6">

        {/* Left Side: The Chart */}
        <div className="flex-1 space-y-6">
          <Card>
            <CardHeader className="pb-4">
              <CardTitle className="text-lg flex items-center gap-2">
                <CircleDashed className="h-5 w-5 text-blue-500" />
                Odontogram
              </CardTitle>
            </CardHeader>
            <CardContent>
              {/* Upper Arch */}
              <div className="mb-6">
                <div className="text-center text-xs text-muted-foreground mb-2 tracking-widest font-medium uppercase">Maxillary (Upper)</div>
                <div className="flex justify-center gap-1 md:gap-2">
                  {TOOTH_NUMBERS.upper.map(t => renderToothSVG(t, true))}
                </div>
              </div>

              {/* Lower Arch */}
              <div>
                <div className="flex justify-center gap-1 md:gap-2">
                  {TOOTH_NUMBERS.lower.map(t => renderToothSVG(t, false))}
                </div>
                <div className="text-center text-xs text-muted-foreground mt-2 tracking-widest font-medium uppercase">Mandibular (Lower)</div>
              </div>

              {/* Legend */}
              <div className="mt-8 flex flex-wrap gap-4 justify-center text-sm">
                {Object.entries(CONDITION_COLORS).map(([condition, color]) => (
                  <div key={condition} className="flex items-center gap-1.5">
                    <div className="w-3 h-3 rounded-full" style={{ backgroundColor: color }}></div>
                    <span className="capitalize">{condition.replace('_', ' ')}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Right Side: Selected Tooth Details & History */}
        <div className="w-[350px] space-y-4">
          <Card className="h-full">
            <CardHeader>
              <CardTitle>Tooth Details</CardTitle>
              <CardDescription>
                {selectedTooth ? `Tooth #${selectedTooth}` : 'Select a tooth on the chart to view details or add conditions.'}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {selectedTooth ? (
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <h3 className="font-semibold text-lg">Tooth {selectedTooth}</h3>
                    <Button size="sm" onClick={() => setAddConditionOpen(true)}>
                      <Plus className="h-4 w-4 mr-1" /> Add
                    </Button>
                  </div>

                  <div className="space-y-3 mt-4">
                    {getConditionsForTooth(selectedTooth).length === 0 && (
                      <div className="text-center py-6 text-muted-foreground border rounded-lg bg-slate-50">
                        No conditions recorded.
                      </div>
                    )}

                    {getConditionsForTooth(selectedTooth).map(c => (
                      <div key={c.id} className="p-3 border rounded-lg bg-white shadow-sm flex flex-col gap-2 relative group">
                        <div className="flex justify-between items-start">
                          <div className="flex items-center gap-2">
                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: CONDITION_COLORS[c.condition_type] || '#000' }}></div>
                            <span className="font-semibold capitalize">{c.condition_type.replace('_', ' ')}</span>
                          </div>
                          <Badge variant="outline" className="capitalize text-xs">{c.status}</Badge>
                        </div>

                        <div className="text-sm text-slate-600 grid grid-cols-2 gap-1">
                          {c.surface && <span><span className="text-slate-400">Surface:</span> {c.surface}</span>}
                          {c.severity && <span><span className="text-slate-400">Severity:</span> {c.severity}</span>}
                          {c.material && <span className="col-span-2"><span className="text-slate-400">Material:</span> {c.material}</span>}
                        </div>

                        {c.notes && <p className="text-xs text-slate-500 italic">"{c.notes}"</p>}

                        <Button 
                          variant="destructive" 
                          size="sm" 
                          className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity h-6 w-6 p-0"
                          onClick={() => removeMut.mutate(c.id)}
                        >
                          X
                        </Button>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="h-40 flex items-center justify-center text-muted-foreground flex-col">
                  <Activity className="h-8 w-8 mb-2 opacity-20" />
                  Select a tooth to begin
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>

      {/* History Timeline */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <History className="h-5 w-5 text-slate-500" />
            Charting History
          </CardTitle>
        </CardHeader>
        <CardContent>
          {history.length === 0 ? (
            <div className="text-center py-6 text-muted-foreground">No charting history available.</div>
          ) : (
            <div className="space-y-4">
              {history.map(entry => (
                <div key={entry.id} className="flex gap-4 items-start pb-4 border-b last:border-0">
                  <div className="mt-1">
                    {entry.entry_type === 'condition' ? <ShieldAlert className="h-5 w-5 text-blue-500"/> : <CheckCircle2 className="h-5 w-5 text-green-500"/>}
                  </div>
                  <div>
                    <p className="font-medium">
                      Tooth #{entry.tooth_number} - <span className="capitalize">{entry.data?.condition_type?.replace('_', ' ')}</span> {entry.data?.action}
                    </p>
                    <p className="text-sm text-muted-foreground">
                      {format(new Date(entry.created_at), 'MMM d, yyyy h:mm a')}
                      {entry.data?.surface && ` • Surface: ${entry.data.surface}`}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Add Condition Dialog */}
      <Dialog open={addConditionOpen} onOpenChange={setAddConditionOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Condition for Tooth #{selectedTooth}</DialogTitle>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Condition</Label>
                <Select value={formData.condition_type} onValueChange={(v) => setFormData({...formData, condition_type: v})}>
                  <SelectTrigger><SelectValue/></SelectTrigger>
                  <SelectContent>
                    {Object.keys(CONDITION_COLORS).map(c => (
                      <SelectItem key={c} value={c} className="capitalize">{c.replace('_', ' ')}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label>Status</Label>
                <Select value={formData.status} onValueChange={(v) => setFormData({...formData, status: v})}>
                  <SelectTrigger><SelectValue/></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="existing">Existing</SelectItem>
                    <SelectItem value="planned">Planned Treatment</SelectItem>
                    <SelectItem value="completed">Completed Treatment</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Surface(s) (e.g. MOD)</Label>
                <Input value={formData.surface} onChange={(e) => setFormData({...formData, surface: e.target.value.toUpperCase()})} placeholder="O, M, D, B, L" />
              </div>
              <div>
                <Label>Severity</Label>
                <Input value={formData.severity} onChange={(e) => setFormData({...formData, severity: e.target.value})} placeholder="e.g. Moderate" />
              </div>
            </div>

            <div>
              <Label>Notes</Label>
              <Input value={formData.notes} onChange={(e) => setFormData({...formData, notes: e.target.value})} placeholder="Additional details..." />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setAddConditionOpen(false)}>Cancel</Button>
            <Button onClick={handleAddSubmit} disabled={addMut.isPending}>Save Condition</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

    </div>
  );
}

// ============================================
// Attachments List Component
// Display and manage patient file attachments
// ============================================

import { useState, useRef } from 'react';
import { format, parseISO } from 'date-fns';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { 
  Upload, 
  File, 
  FileText, 
  Image, 
  Download, 
  Trash2, 
  MoreHorizontal,
  FileCheck,
  Send,
  CloudOff,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { patientApi } from '@/services/patientApi';
import type { PatientAttachment } from '@/types/patient';
import { attachmentCategoryConfig } from '@/types/patient';

interface AttachmentsListProps {
  attachments: PatientAttachment[];
  patientId: string;
  onUpload: () => void;
  onDelete: () => void;
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function getFileIcon(type: string) {
  if (type.startsWith('image/')) return Image;
  if (type === 'application/pdf') return FileText;
  return File;
}

export function AttachmentsList({
  attachments,
  patientId,
  onUpload,
  onDelete,
}: AttachmentsListProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedCategory, setSelectedCategory] = useState<PatientAttachment['category']>('other');
  const [isUploading, setIsUploading] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [filterCategory, setFilterCategory] = useState<string>('all');

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      await patientApi.uploadAttachment(patientId, file, selectedCategory);
      onUpload();
    } catch {
      // Upload failed - user can retry
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await patientApi.deleteAttachment(patientId, deleteId);
      onDelete();
    } catch {
      // Delete failed - user can retry
    } finally {
      setDeleteId(null);
    }
  };

  const filteredAttachments = filterCategory === 'all' 
    ? attachments 
    : attachments.filter(a => a.category === filterCategory);

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle>Files & Attachments</CardTitle>
        <div className="flex items-center gap-2">
          <Select value={filterCategory} onValueChange={setFilterCategory}>
            <SelectTrigger className="w-[140px]">
              <SelectValue placeholder="Filter" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Files</SelectItem>
              {Object.entries(attachmentCategoryConfig).map(([key, config]) => (
                <SelectItem key={key} value={key}>
                  {config.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          
          <div className="flex items-center gap-2">
            <Select
              value={selectedCategory}
              onValueChange={(value) => setSelectedCategory(value as PatientAttachment['category'])}
            >
              <SelectTrigger className="w-[130px]">
                <SelectValue placeholder="Category" />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(attachmentCategoryConfig).map(([key, config]) => (
                  <SelectItem key={key} value={key}>
                    {config.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            
            <input
              ref={fileInputRef}
              type="file"
              onChange={handleFileSelect}
              className="hidden"
              accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"
            />
            <Button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isUploading}
              className="gap-2"
            >
              <Upload className="h-4 w-4" />
              {isUploading ? 'Uploading...' : 'Upload'}
            </Button>
          </div>
        </div>
      </CardHeader>
      
      <CardContent>
        {/* Cloud storage notice */}
        <div className="mb-4 p-3 rounded-lg bg-muted/50 border border-dashed flex items-center gap-3">
          <CloudOff className="h-5 w-5 text-muted-foreground" />
          <div className="text-sm text-muted-foreground">
            <p>File storage requires Lovable Cloud to be enabled.</p>
            <p className="text-xs">Enable Cloud for persistent file uploads.</p>
          </div>
        </div>

        {filteredAttachments.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
            <File className="h-12 w-12 mb-2 opacity-30" />
            <p>No files attached</p>
            <p className="text-sm">Upload files to attach them to this patient</p>
          </div>
        ) : (
          <div className="space-y-2">
            {filteredAttachments.map((attachment) => {
              const Icon = getFileIcon(attachment.type);
              const categoryConfig = attachmentCategoryConfig[attachment.category];

              return (
                <div
                  key={attachment.id}
                  className="flex items-center justify-between p-3 rounded-lg border hover:bg-muted/50 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-lg bg-muted flex items-center justify-center">
                      <Icon className="h-5 w-5 text-muted-foreground" />
                    </div>
                    <div>
                      <div className="font-medium text-sm">{attachment.name}</div>
                      <div className="flex items-center gap-2 text-xs text-muted-foreground">
                        <Badge variant="outline" className="text-xs">
                          {categoryConfig.label}
                        </Badge>
                        <span>{formatFileSize(attachment.size)}</span>
                        <span>•</span>
                        <span>{format(parseISO(attachment.uploadedAt), 'MMM d, yyyy')}</span>
                      </div>
                    </div>
                  </div>

                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon">
                        <MoreHorizontal className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem asChild>
                        <a href={attachment.url} download={attachment.name}>
                          <Download className="h-4 w-4 mr-2" />
                          Download
                        </a>
                      </DropdownMenuItem>
                      <DropdownMenuItem 
                        onClick={() => setDeleteId(attachment.id)}
                        className="text-destructive"
                      >
                        <Trash2 className="h-4 w-4 mr-2" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Attachment?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. The file will be permanently deleted.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Card>
  );
}

// ============================================
// Appointment Dialog Component
// Create and edit appointments
// ============================================

import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { format } from 'date-fns';
import { CalendarIcon, Search, X } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command';
import { cn } from '@/lib/utils';
import type { ScheduleAppointment, AppointmentFormData, PatientSearchResult, ScheduleProvider } from '@/types/scheduling';
import type { Chair, AppointmentTypeConfig } from '@/types/clinic';
import { schedulingApi } from '@/services/schedulingApi';

const appointmentSchema = z.object({
  patientId: z.string().min(1, 'Patient is required'),
  patientName: z.string().min(1, 'Patient name is required'),
  providerId: z.string().min(1, 'Provider is required'),
  chairId: z.string().min(1, 'Chair is required'),
  type: z.string().min(1, 'Appointment type is required'),
  date: z.date({ required_error: 'Date is required' }),
  startTime: z.string().min(1, 'Start time is required'),
  duration: z.number().min(15, 'Duration must be at least 15 minutes'),
  notes: z.string().optional(),
});

type FormData = z.infer<typeof appointmentSchema>;

interface AppointmentDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  appointment?: ScheduleAppointment | null;
  chairs: Chair[];
  providers: ScheduleProvider[];
  appointmentTypes: AppointmentTypeConfig[];
  defaultDate?: Date;
  defaultChairId?: string;
  defaultTime?: string;
  onSave: (data: AppointmentFormData) => Promise<void>;
}

// Generate time options in 15-minute intervals
function generateTimeOptions() {
  const times: string[] = [];
  for (let hour = 7; hour < 20; hour++) {
    for (let minute = 0; minute < 60; minute += 15) {
      const timeStr = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
      times.push(timeStr);
    }
  }
  return times;
}

const TIME_OPTIONS = generateTimeOptions();

export function AppointmentDialog({
  open,
  onOpenChange,
  appointment,
  chairs,
  providers,
  appointmentTypes,
  defaultDate,
  defaultChairId,
  defaultTime,
  onSave,
}: AppointmentDialogProps) {
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<PatientSearchResult[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPatient, setSelectedPatient] = useState<PatientSearchResult | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const isEditing = !!appointment;

  const form = useForm<FormData>({
    resolver: zodResolver(appointmentSchema),
    defaultValues: {
      patientId: '',
      patientName: '',
      providerId: providers[0]?.id || '',
      chairId: defaultChairId || chairs[0]?.id || '',
      type: appointmentTypes[0]?.name.toLowerCase().replace(/ /g, '_') || 'exam',
      date: defaultDate || new Date(),
      startTime: defaultTime || '09:00',
      duration: 30,
      notes: '',
    },
  });

  // Reset form when dialog opens/closes or appointment changes
  useEffect(() => {
    if (open) {
      if (appointment) {
        form.reset({
          patientId: appointment.patientId,
          patientName: appointment.patientName,
          providerId: appointment.providerId,
          chairId: appointment.chairId,
          type: appointment.type,
          date: appointment.startTime,
          startTime: format(appointment.startTime, 'HH:mm'),
          duration: appointment.duration,
          notes: appointment.notes || '',
        });
        setSelectedPatient({
          id: appointment.patientId,
          name: appointment.patientName,
          phone: appointment.patientPhone || '',
          email: '',
        });
      } else {
        form.reset({
          patientId: '',
          patientName: '',
          providerId: providers[0]?.id || '',
          chairId: defaultChairId || chairs[0]?.id || '',
          type: appointmentTypes[0]?.name.toLowerCase().replace(/ /g, '_') || 'exam',
          date: defaultDate || new Date(),
          startTime: defaultTime || '09:00',
          duration: 30,
          notes: '',
        });
        setSelectedPatient(null);
        setSearchQuery('');
      }
    }
  }, [open, appointment, form, providers, chairs, appointmentTypes, defaultDate, defaultChairId, defaultTime]);

  // Search patients
  useEffect(() => {
    const searchPatients = async () => {
      if (searchQuery.length >= 2) {
        setIsSearching(true);
        try {
          const results = await schedulingApi.searchPatients(searchQuery);
          setSearchResults(results);
        } catch {
          // Search failed - results will remain empty
        } finally {
          setIsSearching(false);
        }
      } else {
        setSearchResults([]);
      }
    };

    const debounce = setTimeout(searchPatients, 300);
    return () => clearTimeout(debounce);
  }, [searchQuery]);

  const handlePatientSelect = (patient: PatientSearchResult) => {
    setSelectedPatient(patient);
    form.setValue('patientId', patient.id);
    form.setValue('patientName', patient.name);
    setSearchQuery('');
    setSearchResults([]);
  };

  const handleClearPatient = () => {
    setSelectedPatient(null);
    form.setValue('patientId', '');
    form.setValue('patientName', '');
  };

  const handleTypeChange = (typeName: string) => {
    const typeConfig = appointmentTypes.find(t => t.name === typeName);
    if (typeConfig) {
      form.setValue('type', typeName.toLowerCase().replace(/ /g, '_'));
      form.setValue('duration', typeConfig.duration);
    }
  };

  const onSubmit = async (data: FormData) => {
    setIsSaving(true);
    try {
      await onSave({
        patientId: data.patientId,
        patientName: data.patientName,
        providerId: data.providerId,
        chairId: data.chairId,
        type: data.type as AppointmentFormData['type'],
        date: data.date,
        startTime: data.startTime,
        duration: data.duration,
        notes: data.notes,
      });
      onOpenChange(false);
    } catch {
      // Save failed - dialog remains open for user to retry
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? 'Edit Appointment' : 'New Appointment'}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
          {/* Patient Search */}
          <div className="space-y-2">
            <Label>Patient</Label>
            {selectedPatient ? (
              <div className="flex items-center gap-2 p-2 border rounded-md bg-muted/50">
                <div className="flex-1">
                  <div className="font-medium">{selectedPatient.name}</div>
                  <div className="text-sm text-muted-foreground">{selectedPatient.phone}</div>
                </div>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  onClick={handleClearPatient}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            ) : (
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search by name, phone, or email..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-9"
                />
                {searchResults.length > 0 && (
                  <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-md">
                    <Command>
                      <CommandList>
                        <CommandGroup>
                          {searchResults.map((patient) => (
                            <CommandItem
                              key={patient.id}
                              onSelect={() => handlePatientSelect(patient)}
                              className="cursor-pointer"
                            >
                              <div>
                                <div className="font-medium">{patient.name}</div>
                                <div className="text-sm text-muted-foreground">
                                  {patient.phone} • {patient.email}
                                </div>
                              </div>
                            </CommandItem>
                          ))}
                        </CommandGroup>
                      </CommandList>
                    </Command>
                  </div>
                )}
                {isSearching && (
                  <div className="absolute right-3 top-1/2 -translate-y-1/2">
                    <div className="h-4 w-4 animate-spin rounded-full border-2 border-primary border-t-transparent" />
                  </div>
                )}
              </div>
            )}
            {form.formState.errors.patientId && (
              <p className="text-sm text-destructive">
                {form.formState.errors.patientId.message}
              </p>
            )}
          </div>

          {/* Appointment Type */}
          <div className="space-y-2">
            <Label>Appointment Type</Label>
            <Select
              value={appointmentTypes.find(t => 
                t.name.toLowerCase().replace(/ /g, '_') === form.watch('type')
              )?.name || ''}
              onValueChange={handleTypeChange}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select type" />
              </SelectTrigger>
              <SelectContent>
                {appointmentTypes.map((type) => (
                  <SelectItem key={type.id} value={type.name}>
                    <div className="flex items-center gap-2">
                      <div 
                        className="w-3 h-3 rounded-full"
                        style={{ backgroundColor: type.color }}
                      />
                      {type.name} ({type.duration} min)
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Provider and Chair - Side by side */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Provider</Label>
              <Select
                value={form.watch('providerId')}
                onValueChange={(value) => form.setValue('providerId', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select provider" />
                </SelectTrigger>
                <SelectContent>
                  {providers.map((provider) => (
                    <SelectItem key={provider.id} value={provider.id}>
                      {provider.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Chair / Operatory</Label>
              <Select
                value={form.watch('chairId')}
                onValueChange={(value) => form.setValue('chairId', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select chair" />
                </SelectTrigger>
                <SelectContent>
                  {chairs.map((chair) => (
                    <SelectItem key={chair.id} value={chair.id}>
                      <div className="flex items-center gap-2">
                        <div 
                          className="w-3 h-3 rounded-full"
                          style={{ backgroundColor: chair.color }}
                        />
                        {chair.name}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Date, Time, Duration */}
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label>Date</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !form.watch('date') && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {form.watch('date') ? format(form.watch('date'), 'MMM d') : 'Pick date'}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="single"
                    selected={form.watch('date')}
                    onSelect={(date) => date && form.setValue('date', date)}
                    initialFocus
                    className={cn("p-3 pointer-events-auto")}
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label>Time</Label>
              <Select
                value={form.watch('startTime')}
                onValueChange={(value) => form.setValue('startTime', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select time" />
                </SelectTrigger>
                <SelectContent>
                  {TIME_OPTIONS.map((time) => {
                    const [hour, minute] = time.split(':').map(Number);
                    const displayTime = hour > 12 
                      ? `${hour - 12}:${minute.toString().padStart(2, '0')} PM`
                      : hour === 12
                        ? `12:${minute.toString().padStart(2, '0')} PM`
                        : `${hour}:${minute.toString().padStart(2, '0')} AM`;
                    return (
                      <SelectItem key={time} value={time}>
                        {displayTime}
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Duration</Label>
              <Select
                value={form.watch('duration').toString()}
                onValueChange={(value) => form.setValue('duration', parseInt(value))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Duration" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="15">15 min</SelectItem>
                  <SelectItem value="30">30 min</SelectItem>
                  <SelectItem value="45">45 min</SelectItem>
                  <SelectItem value="60">1 hour</SelectItem>
                  <SelectItem value="90">1.5 hours</SelectItem>
                  <SelectItem value="120">2 hours</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Notes */}
          <div className="space-y-2">
            <Label>Notes (optional)</Label>
            <Textarea
              placeholder="Add any notes for this appointment..."
              {...form.register('notes')}
              rows={2}
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={isSaving}>
              {isSaving ? 'Saving...' : isEditing ? 'Update' : 'Create Appointment'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

// ============================================
// Day View Component
// Shows appointments for a single day with chair columns
// ============================================

import { useMemo, useCallback, memo } from 'react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { AppointmentCard } from './AppointmentCard';
import { cn } from '@/lib/utils';
import type { ScheduleAppointment } from '@/types/scheduling';
import type { Chair } from '@/types/clinic';
import { generateTimeSlots, calculateAppointmentPosition } from '@/types/scheduling';

interface DayViewProps {
  date: Date;
  chairs: Chair[];
  appointments: ScheduleAppointment[];
  onAppointmentClick: (appointment: ScheduleAppointment) => void;
  onStatusChange: (id: string, status: string) => void;
  onEditAppointment: (appointment: ScheduleAppointment) => void;
  onCancelAppointment: (id: string) => void;
  onDropAppointment: (appointmentId: string, chairId: string, time: string) => void;
  canEdit?: boolean;
  startHour?: number;
  endHour?: number;
}

export const DayView = memo(function DayView({
  date,
  chairs,
  appointments,
  onAppointmentClick,
  onStatusChange,
  onEditAppointment,
  onCancelAppointment,
  onDropAppointment,
  canEdit = true,
  startHour = 7,
  endHour = 19,
}: DayViewProps) {
  const timeSlots = useMemo(() => generateTimeSlots(startHour, endHour), [startHour, endHour]);

  const getChairAppointments = useCallback((chairId: string) => {
    return appointments.filter(apt => apt.chairId === chairId);
  }, [appointments]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, chairId: string, time: string) => {
    e.preventDefault();
    const appointmentId = e.dataTransfer.getData('appointmentId');
    if (appointmentId) {
      onDropAppointment(appointmentId, chairId, time);
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header with chair names */}
      <div className="flex border-b sticky top-0 bg-background z-10">
        <div className="w-20 flex-shrink-0 p-2 text-xs text-muted-foreground font-medium border-r">
          Time
        </div>
        {chairs.map((chair) => (
          <div 
            key={chair.id}
            className="flex-1 min-w-[200px] p-2 text-center border-r last:border-r-0"
          >
            <div className="flex items-center justify-center gap-2">
              <div 
                className="w-3 h-3 rounded-full"
                style={{ backgroundColor: chair.color }}
              />
              <span className="font-medium text-sm">{chair.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Time grid */}
      <ScrollArea className="flex-1">
        <div className="flex">
          {/* Time labels column */}
          <div className="w-20 flex-shrink-0 border-r">
            {timeSlots.map((slot, index) => (
              <div
                key={slot.time}
                className={cn(
                  "h-[60px] px-2 text-right text-xs text-muted-foreground border-b flex items-start pt-1",
                  slot.isHalfHour && "border-b-dashed"
                )}
              >
                {!slot.isHalfHour && (
                  <span className={cn(index === 0 ? "" : "relative -top-2")}>
                    {slot.hour > 12 
                      ? `${slot.hour - 12}:00 PM` 
                      : slot.hour === 12 
                        ? '12:00 PM'
                        : `${slot.hour}:00 AM`
                    }
                  </span>
                )}
              </div>
            ))}
          </div>

          {/* Chair columns */}
          {chairs.map((chair) => (
            <div 
              key={chair.id}
              className="flex-1 min-w-[200px] border-r last:border-r-0 relative"
            >
              {/* Time slot grid */}
              {timeSlots.map((slot) => (
                <div
                  key={slot.time}
                  className={cn(
                    "h-[60px] border-b hover:bg-muted/50 transition-colors",
                    slot.isHalfHour && "border-b-dashed"
                  )}
                  onDragOver={handleDragOver}
                  onDrop={(e) => handleDrop(e, chair.id, slot.time)}
                />
              ))}

              {/* Appointments overlay */}
              <div className="absolute inset-0 pointer-events-none">
                {getChairAppointments(chair.id).map((appointment) => {
                  const { top, height } = calculateAppointmentPosition(
                    appointment.startTime,
                    appointment.endTime,
                    startHour
                  );

                  return (
                    <div key={appointment.id} className="pointer-events-auto">
                      <AppointmentCard
                        appointment={appointment}
                        style={{ top, height, position: 'absolute', left: 4, right: 4 }}
                        onClick={() => onAppointmentClick(appointment)}
                        onStatusChange={(status) => onStatusChange(appointment.id, status)}
                        onEdit={() => onEditAppointment(appointment)}
                        onCancel={() => onCancelAppointment(appointment.id)}
                        canEdit={canEdit}
                      />
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </ScrollArea>
    </div>
  );
});

// ============================================
// Month View Component
// Calendar grid showing appointments for a month
// ============================================

import { useMemo } from 'react';
import { 
  format, 
  startOfMonth, 
  endOfMonth, 
  startOfWeek, 
  endOfWeek, 
  eachDayOfInterval,
  isSameMonth,
  isSameDay,
  isToday 
} from 'date-fns';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import type { ScheduleAppointment } from '@/types/scheduling';
import { appointmentStatusConfig } from '@/types/scheduling';
import { defaultAppointmentTypes } from '@/types/clinic';

interface MonthViewProps {
  currentDate: Date;
  appointments: ScheduleAppointment[];
  onDayClick: (date: Date) => void;
  onAppointmentClick: (appointment: ScheduleAppointment) => void;
}

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

export function MonthView({
  currentDate,
  appointments,
  onDayClick,
  onAppointmentClick,
}: MonthViewProps) {
  // Generate all days to display in the calendar grid
  const calendarDays = useMemo(() => {
    const monthStart = startOfMonth(currentDate);
    const monthEnd = endOfMonth(currentDate);
    const calendarStart = startOfWeek(monthStart, { weekStartsOn: 0 });
    const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 0 });

    return eachDayOfInterval({ start: calendarStart, end: calendarEnd });
  }, [currentDate]);

  const getAppointmentsForDay = (date: Date) => {
    return appointments.filter(apt => isSameDay(apt.startTime, date));
  };

  return (
    <div className="flex flex-col h-full">
      {/* Weekday headers */}
      <div className="grid grid-cols-7 border-b">
        {WEEKDAYS.map((day) => (
          <div 
            key={day}
            className="p-2 text-center text-sm font-medium text-muted-foreground border-r last:border-r-0"
          >
            {day}
          </div>
        ))}
      </div>

      {/* Calendar grid */}
      <div className="flex-1 grid grid-cols-7 grid-rows-[repeat(auto-fill,minmax(120px,1fr))]">
        {calendarDays.map((day) => {
          const dayAppointments = getAppointmentsForDay(day);
          const isCurrentMonth = isSameMonth(day, currentDate);
          const isCurrentDay = isToday(day);

          return (
            <div
              key={day.toISOString()}
              className={cn(
                "min-h-[120px] border-r border-b p-1 cursor-pointer hover:bg-muted/50 transition-colors",
                !isCurrentMonth && "bg-muted/30 text-muted-foreground",
                isCurrentDay && "bg-primary/5"
              )}
              onClick={() => onDayClick(day)}
            >
              {/* Day number */}
              <div className={cn(
                "text-sm font-medium mb-1",
                isCurrentDay && "text-primary"
              )}>
                <span className={cn(
                  "inline-flex items-center justify-center w-6 h-6 rounded-full",
                  isCurrentDay && "bg-primary text-primary-foreground"
                )}>
                  {format(day, 'd')}
                </span>
              </div>

              {/* Appointments preview */}
              <ScrollArea className="h-[calc(100%-24px)]">
                <div className="space-y-1">
                  {dayAppointments.slice(0, 3).map((appointment) => {
                    const typeConfig = defaultAppointmentTypes.find(t => 
                      t.name.toLowerCase().includes(appointment.type.replace('_', ' '))
                    );

                    return (
                      <div
                        key={appointment.id}
                        className="text-xs p-1 rounded truncate cursor-pointer hover:opacity-80"
                        style={{ 
                          backgroundColor: `${typeConfig?.color || '#6B7280'}20`,
                          borderLeft: `2px solid ${typeConfig?.color || '#6B7280'}`
                        }}
                        onClick={(e) => {
                          e.stopPropagation();
                          onAppointmentClick(appointment);
                        }}
                      >
                        <span className="font-medium">
                          {format(appointment.startTime, 'h:mm a')}
                        </span>
                        {' '}
                        <span className="text-muted-foreground">
                          {appointment.patientName}
                        </span>
                      </div>
                    );
                  })}

                  {dayAppointments.length > 3 && (
                    <div className="text-xs text-muted-foreground text-center">
                      +{dayAppointments.length - 3} more
                    </div>
                  )}
                </div>
              </ScrollArea>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ============================================
// CoreDent PMS - Appointment Types Tab
// Configure appointment types and durations
// ============================================

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Calendar, Plus, Pencil, Trash2, Loader2, Save, Clock, Globe } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { z } from 'zod';
import type { AppointmentTypeConfig } from '@/types/clinic';
import { clinicApi } from '@/services/clinicApi';

const appointmentTypeSchema = z.object({
  name: z.string().trim().min(1, 'Name is required').max(50),
  code: z.string().trim().min(1, 'Code is required').max(10),
  duration: z.number().min(5, 'Minimum 5 minutes').max(480, 'Maximum 8 hours'),
  color: z.string().regex(/^#[0-9A-Fa-f]{6}$/, 'Please select a valid color'),
  description: z.string().max(200).optional(),
  allowOnlineBooking: z.boolean(),
});

interface AppointmentTypesTabProps {
  appointmentTypes: AppointmentTypeConfig[];
  onUpdate: (types: AppointmentTypeConfig[]) => void;
}

const PRESET_COLORS = [
  '#3B82F6', '#10B981', '#8B5CF6', '#F59E0B', '#EF4444',
  '#EC4899', '#6366F1', '#14B8A6', '#F97316', '#84CC16',
];

const DURATION_OPTIONS = [
  { value: 15, label: '15 min' },
  { value: 30, label: '30 min' },
  { value: 45, label: '45 min' },
  { value: 60, label: '1 hour' },
  { value: 90, label: '1.5 hours' },
  { value: 120, label: '2 hours' },
  { value: 180, label: '3 hours' },
];

export function AppointmentTypesTab({ appointmentTypes, onUpdate }: AppointmentTypesTabProps) {
  const [types, setTypes] = useState<AppointmentTypeConfig[]>([...appointmentTypes]);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingType, setEditingType] = useState<AppointmentTypeConfig | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    code: '',
    duration: 30,
    color: '#3B82F6',
    description: '',
    allowOnlineBooking: false,
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const { toast } = useToast();

  const openAddDialog = () => {
    setEditingType(null);
    setFormData({
      name: '',
      code: '',
      duration: 30,
      color: '#3B82F6',
      description: '',
      allowOnlineBooking: false,
    });
    setErrors({});
    setIsDialogOpen(true);
  };

  const openEditDialog = (type: AppointmentTypeConfig) => {
    setEditingType(type);
    setFormData({
      name: type.name,
      code: type.code,
      duration: type.duration,
      color: type.color,
      description: type.description || '',
      allowOnlineBooking: type.allowOnlineBooking,
    });
    setErrors({});
    setIsDialogOpen(true);
  };

  const handleSubmit = () => {
    setErrors({});

    const result = appointmentTypeSchema.safeParse(formData);
    if (!result.success) {
      const fieldErrors: Record<string, string> = {};
      result.error.issues.forEach((issue) => {
        fieldErrors[issue.path[0] as string] = issue.message;
      });
      setErrors(fieldErrors);
      return;
    }

    if (editingType) {
      // Update existing type
      setTypes(prev =>
        prev.map(t =>
          t.id === editingType.id
            ? { ...t, ...formData }
            : t
        )
      );
      toast({ title: 'Updated', description: `${formData.name} has been updated.` });
    } else {
      // Add new type
      const newType: AppointmentTypeConfig = {
        id: Date.now().toString(),
        ...formData,
        isActive: true,
      };
      setTypes(prev => [...prev, newType]);
      toast({ title: 'Added', description: `${formData.name} has been added.` });
    }

    setIsDialogOpen(false);
  };

  const toggleTypeStatus = (id: string) => {
    setTypes(prev =>
      prev.map(t => (t.id === id ? { ...t, isActive: !t.isActive } : t))
    );
  };

  const deleteType = (id: string) => {
    const type = types.find(t => t.id === id);
    setTypes(prev => prev.filter(t => t.id !== id));
    toast({
      title: 'Deleted',
      description: `${type?.name} has been removed.`,
    });
  };

  const handleSaveAll = async () => {
    setIsSaving(true);

    try {
      const response = await clinicApi.updateSettings({ appointmentTypes: types });
      if (!response.success || !response.data) {
        throw new Error(response.error?.message || 'Failed to save appointment types');
      }
      setTypes(response.data.appointmentTypes);
      onUpdate(response.data.appointmentTypes);
      toast({ title: 'Saved', description: 'Appointment types have been saved.' });
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Failed to save. Please try again.',
      });
    } finally {
      setIsSaving(false);
    }
  };

  const formatDuration = (minutes: number) => {
    if (minutes < 60) return `${minutes} min`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins > 0 ? `${hours}h ${mins}m` : `${hours} hour${hours > 1 ? 's' : ''}`;
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-5 w-5" />
              Appointment Types
            </CardTitle>
            <CardDescription>
              Configure the types of appointments your practice offers
            </CardDescription>
          </div>
          <Button onClick={openAddDialog} className="gap-2">
            <Plus className="h-4 w-4" />
            Add Type
          </Button>
        </CardHeader>
        <CardContent>
          {types.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Calendar className="h-12 w-12 text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No appointment types</h3>
              <p className="text-muted-foreground">Add your first appointment type</p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Type</TableHead>
                  <TableHead>Code</TableHead>
                  <TableHead>Duration</TableHead>
                  <TableHead>Online Booking</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="w-[100px]">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {types.map((type) => (
                  <TableRow key={type.id}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <div
                          className="h-4 w-4 rounded-full"
                          style={{ backgroundColor: type.color }}
                        />
                        <span className="font-medium">{type.name}</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <code className="text-sm bg-muted px-1.5 py-0.5 rounded">
                        {type.code}
                      </code>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1 text-muted-foreground">
                        <Clock className="h-3 w-3" />
                        {formatDuration(type.duration)}
                      </div>
                    </TableCell>
                    <TableCell>
                      {type.allowOnlineBooking ? (
                        <Badge variant="secondary" className="gap-1">
                          <Globe className="h-3 w-3" />
                          Enabled
                        </Badge>
                      ) : (
                        <span className="text-muted-foreground text-sm">—</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={type.isActive}
                          onCheckedChange={() => toggleTypeStatus(type.id)}
                        />
                        <Badge variant={type.isActive ? 'default' : 'secondary'}>
                          {type.isActive ? 'Active' : 'Inactive'}
                        </Badge>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-1">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => openEditDialog(type)}
                        >
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="text-destructive"
                          onClick={() => deleteType(type.id)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSaveAll} disabled={isSaving} size="lg" className="gap-2">
          {isSaving ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              Save Types
            </>
          )}
        </Button>
      </div>

      {/* Add/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>
              {editingType ? 'Edit Appointment Type' : 'Add Appointment Type'}
            </DialogTitle>
            <DialogDescription>
              Configure the appointment type details
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="typeName">Name *</Label>
                <Input
                  id="typeName"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className={errors.name ? 'border-destructive' : ''}
                  placeholder="Cleaning"
                />
                {errors.name && (
                  <p className="text-sm text-destructive">{errors.name}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="typeCode">Code *</Label>
                <Input
                  id="typeCode"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
                  className={errors.code ? 'border-destructive' : ''}
                  placeholder="D1110"
                />
                {errors.code && (
                  <p className="text-sm text-destructive">{errors.code}</p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="typeDuration">Duration *</Label>
              <Select
                value={formData.duration.toString()}
                onValueChange={(value) => setFormData({ ...formData, duration: parseInt(value) })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {DURATION_OPTIONS.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value.toString()}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="typeDescription">Description</Label>
              <Input
                id="typeDescription"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Routine dental cleaning and checkup"
              />
            </div>

            <div className="space-y-2">
              <Label>Color</Label>
              <div className="flex flex-wrap gap-2">
                {PRESET_COLORS.map((color) => (
                  <button
                    key={color}
                    type="button"
                    className={`h-8 w-8 rounded-full border-2 transition-all ${
                      formData.color === color
                        ? 'border-foreground scale-110'
                        : 'border-transparent'
                    }`}
                    style={{ backgroundColor: color }}
                    onClick={() => setFormData({ ...formData, color })}
                  />
                ))}
              </div>
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="allowOnlineBooking"
                checked={formData.allowOnlineBooking}
                onCheckedChange={(checked) =>
                  setFormData({ ...formData, allowOnlineBooking: checked === true })
                }
              />
              <Label htmlFor="allowOnlineBooking" className="text-sm font-normal">
                Allow patients to book this appointment type online
              </Label>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit}>
              {editingType ? 'Update' : 'Add'} Type
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ============================================
// Automations Settings Tab
// Configure n8n webhooks for workflow automation
// ============================================

import { useState, useEffect, useCallback } from 'react';
import { useToast } from '@/hooks/use-toast';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Calendar,
  CalendarCheck,
  CalendarPlus,
  CalendarX,
  Bell,
  CheckCircle,
  UserPlus,
  UserX,
  FileCheck,
  FileText,
  CreditCard,
  BarChart3,
  Plus,
  Trash2,
  TestTube,
  Loader2,
  Zap,
  ExternalLink,
  Shield,
  CalendarClock,
  ShieldAlert,
  PackageX,
  Star,
} from 'lucide-react';
import { automationApi } from '@/services/automationApi';
import { ConfirmationDialog } from './ConfirmationDialog';
import type { AutomationWebhook, AutomationEvent, automationEventConfigs } from '@/types/automation';
import { automationEventConfigs as eventConfigs } from '@/types/automation';

const eventIcons: Record<string, React.ReactNode> = {
  'calendar-plus': <CalendarPlus className="h-4 w-4" />,
  'calendar-check': <CalendarCheck className="h-4 w-4" />,
  'calendar-x': <CalendarX className="h-4 w-4" />,
  'calendar-clock': <CalendarClock className="h-4 w-4" />,
  'bell': <Bell className="h-4 w-4" />,
  'check-circle': <CheckCircle className="h-4 w-4" />,
  'user-plus': <UserPlus className="h-4 w-4" />,
  'user-x': <UserX className="h-4 w-4" />,
  'file-check': <FileCheck className="h-4 w-4" />,
  'file-text': <FileText className="h-4 w-4" />,
  'credit-card': <CreditCard className="h-4 w-4" />,
  'bar-chart': <BarChart3 className="h-4 w-4" />,
  'shield-alert': <ShieldAlert className="h-4 w-4" />,
  'package-x': <PackageX className="h-4 w-4" />,
  'star': <Star className="h-4 w-4" />,
};

const categoryColors: Record<string, string> = {
  appointment: 'bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-200',
  patient: 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-200',
  billing: 'bg-amber-100 text-amber-800 dark:bg-amber-900/50 dark:text-amber-200',
  reports: 'bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-200',
  inventory: 'bg-orange-100 text-orange-800 dark:bg-orange-900/50 dark:text-orange-200',
  engagement: 'bg-pink-100 text-pink-800 dark:bg-pink-900/50 dark:text-pink-200',
};

export function AutomationsTab() {
  const { toast } = useToast();
  const [webhooks, setWebhooks] = useState<AutomationWebhook[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingWebhook, setEditingWebhook] = useState<AutomationWebhook | null>(null);
  const [deleteWebhook, setDeleteWebhook] = useState<AutomationWebhook | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isTesting, setIsTesting] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    event: '' as AutomationEvent | '',
    webhookUrl: '',
    secretToken: '',
  });

  const loadWebhooks = useCallback(async () => {
    try {
      setIsLoading(true);
      const data = await automationApi.getWebhooks();
      setWebhooks(data);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load automations',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  }, [toast]);

  useEffect(() => {
    loadWebhooks();
  }, [loadWebhooks]);

  const handleOpenDialog = (webhook?: AutomationWebhook) => {
    if (webhook) {
      setEditingWebhook(webhook);
      setFormData({
        name: webhook.name,
        event: webhook.event,
        webhookUrl: webhook.webhookUrl,
        secretToken: webhook.secretToken || '',
      });
    } else {
      setEditingWebhook(null);
      setFormData({
        name: '',
        event: '',
        webhookUrl: '',
        secretToken: '',
      });
    }
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!formData.name || !formData.event || !formData.webhookUrl) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSaving(true);
      if (editingWebhook) {
        const updated = await automationApi.updateWebhook(editingWebhook.id, {
          name: formData.name,
          event: formData.event as AutomationEvent,
          webhookUrl: formData.webhookUrl,
          secretToken: formData.secretToken || undefined,
        });
        setWebhooks((prev) =>
          prev.map((w) => (w.id === updated.id ? updated : w))
        );
        toast({
          title: 'Automation Updated',
          description: 'Webhook configuration has been updated',
        });
      } else {
        const created = await automationApi.createWebhook({
          name: formData.name,
          event: formData.event as AutomationEvent,
          webhookUrl: formData.webhookUrl,
          secretToken: formData.secretToken || undefined,
          isActive: false,
        });
        setWebhooks((prev) => [...prev, created]);
        toast({
          title: 'Automation Created',
          description: 'New webhook has been configured',
        });
      }
      setIsDialogOpen(false);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to save automation',
        variant: 'destructive',
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleToggle = async (webhook: AutomationWebhook) => {
    if (!webhook.webhookUrl && !webhook.isActive) {
      toast({
        title: 'Configuration Required',
        description: 'Please configure the webhook URL first',
        variant: 'destructive',
      });
      return;
    }

    try {
      const updated = await automationApi.toggleWebhook(webhook.id);
      setWebhooks((prev) =>
        prev.map((w) => (w.id === updated.id ? updated : w))
      );
      toast({
        title: updated.isActive ? 'Automation Enabled' : 'Automation Disabled',
        description: `${webhook.name} is now ${updated.isActive ? 'active' : 'inactive'}`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to toggle automation',
        variant: 'destructive',
      });
    }
  };

  const handleTest = async (webhook: AutomationWebhook) => {
    if (!webhook.webhookUrl) {
      toast({
        title: 'No Webhook URL',
        description: 'Please configure the webhook URL first',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsTesting(webhook.id);
      const success = await automationApi.testWebhook(
        webhook.webhookUrl,
        webhook.secretToken
      );
      toast({
        title: 'Test Sent',
        description: 'Test payload sent to webhook. Check your n8n workflow history.',
      });
    } catch (error) {
      toast({
        title: 'Test Failed',
        description: 'Failed to send test payload',
        variant: 'destructive',
      });
    } finally {
      setIsTesting(null);
    }
  };

  const handleDelete = async () => {
    if (!deleteWebhook) return;

    try {
      await automationApi.deleteWebhook(deleteWebhook.id);
      setWebhooks((prev) => prev.filter((w) => w.id !== deleteWebhook.id));
      toast({
        title: 'Automation Deleted',
        description: 'Webhook configuration has been removed',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to delete automation',
        variant: 'destructive',
      });
    } finally {
      setDeleteWebhook(null);
    }
  };

  const getEventConfig = (event: AutomationEvent) => {
    return eventConfigs.find((e) => e.event === event);
  };

  const groupedWebhooks = webhooks.reduce((acc, webhook) => {
    const config = getEventConfig(webhook.event);
    const category = config?.category || 'other';
    if (!acc[category]) acc[category] = [];
    acc[category].push(webhook);
    return acc;
  }, {} as Record<string, AutomationWebhook[]>);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Workflow Automations</h3>
          <p className="text-sm text-muted-foreground">
            Connect n8n webhooks to automate notifications and workflows
          </p>
        </div>
        <Button onClick={() => handleOpenDialog()}>
          <Plus className="h-4 w-4 mr-2" />
          Add Automation
        </Button>
      </div>

      {/* Info Card */}
      <Card className="border-blue-200 bg-blue-50/50 dark:border-blue-900 dark:bg-blue-950/20">
        <CardContent className="flex gap-4 py-4">
          <Zap className="h-5 w-5 text-blue-600 dark:text-blue-400 shrink-0 mt-0.5" />
          <div className="space-y-1">
            <p className="text-sm font-medium text-blue-900 dark:text-blue-100">
              Powered by n8n Workflows
            </p>
            <p className="text-sm text-blue-700 dark:text-blue-300">
              Create workflows in n8n to send SMS, WhatsApp, emails, update CRMs, and more.
              Each automation triggers your n8n webhook when the event occurs.
            </p>
            <a
              href="https://n8n.io/workflows"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1 text-sm text-blue-600 hover:underline dark:text-blue-400"
            >
              Browse n8n workflow templates
              <ExternalLink className="h-3 w-3" />
            </a>
          </div>
        </CardContent>
      </Card>

      {/* Webhooks List */}
      {webhooks.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12 text-center">
            <Zap className="h-12 w-12 text-muted-foreground/50 mb-4" />
            <h4 className="text-lg font-medium">No automations configured</h4>
            <p className="text-sm text-muted-foreground mt-1 mb-4">
              Add your first automation to connect n8n workflows
            </p>
            <Button onClick={() => handleOpenDialog()}>
              <Plus className="h-4 w-4 mr-2" />
              Add Automation
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-6">
          {['appointment', 'patient', 'billing', 'reports', 'inventory', 'engagement'].map((category) => {
            const categoryWebhooks = groupedWebhooks[category];
            if (!categoryWebhooks?.length) return null;

            return (
              <div key={category}>
                <h4 className="text-sm font-medium text-muted-foreground mb-3 capitalize">
                  {category} Automations
                </h4>
                <div className="space-y-3">
                  {categoryWebhooks.map((webhook) => {
                    const config = getEventConfig(webhook.event);
                    return (
                      <Card key={webhook.id}>
                        <CardContent className="flex items-center gap-4 py-4">
                          {/* Icon */}
                          <div
                            className={`p-2 rounded-lg ${categoryColors[category]}`}
                          >
                            {config && eventIcons[config.icon]}
                          </div>

                          {/* Info */}
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <h5 className="font-medium truncate">
                                {webhook.name}
                              </h5>
                              {webhook.secretToken && (
                                <Shield className="h-3.5 w-3.5 text-green-600" />
                              )}
                            </div>
                            <p className="text-sm text-muted-foreground truncate">
                              {config?.description || webhook.event}
                            </p>
                            {webhook.lastTriggered && (
                              <p className="text-xs text-muted-foreground mt-1">
                                Last triggered:{' '}
                                {new Date(webhook.lastTriggered).toLocaleString()}
                              </p>
                            )}
                          </div>

                          {/* Status */}
                          <Badge
                            variant={webhook.isActive ? 'default' : 'secondary'}
                            className={
                              webhook.isActive
                                ? 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-200'
                                : ''
                            }
                          >
                            {webhook.isActive ? 'Active' : 'Inactive'}
                          </Badge>

                          {/* Actions */}
                          <div className="flex items-center gap-2">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleTest(webhook)}
                              disabled={isTesting === webhook.id}
                              title="Send test"
                            >
                              {isTesting === webhook.id ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                              ) : (
                                <TestTube className="h-4 w-4" />
                              )}
                            </Button>
                            <Switch
                              checked={webhook.isActive}
                              onCheckedChange={() => handleToggle(webhook)}
                            />
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleOpenDialog(webhook)}
                            >
                              Edit
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => setDeleteWebhook(webhook)}
                              className="text-destructive hover:text-destructive"
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </CardContent>
                      </Card>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>
              {editingWebhook ? 'Edit Automation' : 'Add Automation'}
            </DialogTitle>
            <DialogDescription>
              Configure an n8n webhook to trigger when this event occurs
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="name">Name *</Label>
              <Input
                id="name"
                placeholder="e.g., Appointment Confirmation SMS"
                value={formData.name}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, name: e.target.value }))
                }
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="event">Trigger Event *</Label>
              <Select
                value={formData.event}
                onValueChange={(value) =>
                  setFormData((prev) => ({
                    ...prev,
                    event: value as AutomationEvent,
                  }))
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select an event" />
                </SelectTrigger>
                <SelectContent>
                  {eventConfigs.map((config) => (
                    <SelectItem key={config.event} value={config.event}>
                      <div className="flex items-center gap-2">
                        {eventIcons[config.icon]}
                        <span>{config.label}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {formData.event && (
                <p className="text-xs text-muted-foreground">
                  {getEventConfig(formData.event as AutomationEvent)?.description}
                </p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="webhookUrl">Webhook URL *</Label>
              <Input
                id="webhookUrl"
                placeholder="https://n8n.yourdomain.com/webhook/..."
                value={formData.webhookUrl}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, webhookUrl: e.target.value }))
                }
              />
              <p className="text-xs text-muted-foreground">
                Get this URL from your n8n Webhook node
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="secretToken">Secret Token (Optional)</Label>
              <Input
                id="secretToken"
                type="password"
                placeholder="Your secret token for authentication"
                value={formData.secretToken}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    secretToken: e.target.value,
                  }))
                }
              />
              <p className="text-xs text-muted-foreground flex items-center gap-1">
                <Shield className="h-3 w-3" />
                Sent as Bearer token in Authorization header
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isSaving}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingWebhook ? 'Save Changes' : 'Add Automation'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation */}
      <ConfirmationDialog
        open={!!deleteWebhook}
        onOpenChange={(open) => !open && setDeleteWebhook(null)}
        title="Delete Automation"
        description={`Are you sure you want to delete "${deleteWebhook?.name}"? This action cannot be undone.`}
        confirmText="Delete"
        type="delete"
        onConfirm={handleDelete}
      />
    </div>
  );
}

// ============================================
// CoreDent PMS - Billing Preferences Tab
// Configure billing and invoicing settings
// ============================================

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2, Save, DollarSign, Receipt, Clock, AlertTriangle } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { z } from 'zod';
import type { BillingPreferences, PaymentMethod } from '@/types/settings';
import { paymentMethodLabels, currencyOptions } from '@/types/settings';
import { settingsApi } from '@/services/api';

const billingSchema = z.object({
  taxRate: z.number().min(0).max(100),
  taxLabel: z.string().min(1).max(50),
  defaultPaymentTerms: z.number().min(0).max(365),
  invoicePrefix: z.string().min(1).max(10),
  invoiceStartNumber: z.number().min(1),
  currency: z.string(),
  receiptFooterText: z.string().max(500),
  lateFeePercentage: z.number().min(0).max(100),
  lateFeeGracePeriod: z.number().min(0).max(365),
});

interface BillingPreferencesTabProps {
  preferences: BillingPreferences;
  onUpdate: (preferences: BillingPreferences) => void;
}

export function BillingPreferencesTab({ preferences, onUpdate }: BillingPreferencesTabProps) {
  const { toast } = useToast();
  const [formData, setFormData] = useState<BillingPreferences>(preferences);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);

  const handleInputChange = (field: keyof BillingPreferences, value: string | number | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const handlePaymentMethodToggle = (method: PaymentMethod) => {
    setFormData(prev => {
      const current = prev.acceptedPaymentMethods;
      if (current.includes(method)) {
        // Don't allow removing all payment methods
        if (current.length === 1) {
          toast({
            title: 'Cannot remove',
            description: 'At least one payment method must be selected',
            variant: 'destructive',
          });
          return prev;
        }
        return { ...prev, acceptedPaymentMethods: current.filter(m => m !== method) };
      } else {
        return { ...prev, acceptedPaymentMethods: [...current, method] };
      }
    });
  };

  const handleSave = async () => {
    try {
      // Validate
      const validated = billingSchema.safeParse({
        taxRate: formData.taxRate,
        taxLabel: formData.taxLabel,
        defaultPaymentTerms: formData.defaultPaymentTerms,
        invoicePrefix: formData.invoicePrefix,
        invoiceStartNumber: formData.invoiceStartNumber,
        currency: formData.currency,
        receiptFooterText: formData.receiptFooterText,
        lateFeePercentage: formData.lateFeePercentage,
        lateFeeGracePeriod: formData.lateFeeGracePeriod,
      });

      if (!validated.success) {
        const fieldErrors: Record<string, string> = {};
        validated.error.errors.forEach(err => {
          if (err.path[0]) {
            fieldErrors[err.path[0] as string] = err.message;
          }
        });
        setErrors(fieldErrors);
        return;
      }

      setIsSaving(true);
      const response = await settingsApi.updateBillingPreferences(formData);
      if (!response.success || !response.data) {
        throw new Error(response.error?.message || 'Failed to save preferences');
      }
      onUpdate(response.data);
      toast({
        title: 'Preferences saved',
        description: 'Your billing preferences have been updated',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to save preferences. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Invoice Settings */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Receipt className="h-5 w-5" />
            Invoice Settings
          </CardTitle>
          <CardDescription>
            Configure how invoices are generated and numbered
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="grid gap-6 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="invoicePrefix">Invoice Prefix</Label>
              <Input
                id="invoicePrefix"
                value={formData.invoicePrefix}
                onChange={e => handleInputChange('invoicePrefix', e.target.value)}
                placeholder="INV"
                maxLength={10}
              />
              {errors.invoicePrefix && (
                <p className="text-sm text-destructive">{errors.invoicePrefix}</p>
              )}
              <p className="text-xs text-muted-foreground">
                Example: {formData.invoicePrefix}-{formData.invoiceStartNumber}
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="invoiceStartNumber">Starting Number</Label>
              <Input
                id="invoiceStartNumber"
                type="number"
                min={1}
                value={formData.invoiceStartNumber}
                onChange={e => handleInputChange('invoiceStartNumber', parseInt(e.target.value) || 1)}
              />
              {errors.invoiceStartNumber && (
                <p className="text-sm text-destructive">{errors.invoiceStartNumber}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="currency">Currency</Label>
              <Select
                value={formData.currency}
                onValueChange={value => handleInputChange('currency', value)}
              >
                <SelectTrigger id="currency">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {currencyOptions.map(option => (
                    <SelectItem key={option.code} value={option.code}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="defaultPaymentTerms">Default Payment Terms (days)</Label>
              <Input
                id="defaultPaymentTerms"
                type="number"
                min={0}
                max={365}
                value={formData.defaultPaymentTerms}
                onChange={e => handleInputChange('defaultPaymentTerms', parseInt(e.target.value) || 0)}
              />
              {errors.defaultPaymentTerms && (
                <p className="text-sm text-destructive">{errors.defaultPaymentTerms}</p>
              )}
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Auto-send Invoices</Label>
                <p className="text-sm text-muted-foreground">
                  Automatically email invoices when created
                </p>
              </div>
              <Switch
                checked={formData.autoSendInvoices}
                onCheckedChange={checked => handleInputChange('autoSendInvoices', checked)}
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Auto-send Receipts</Label>
                <p className="text-sm text-muted-foreground">
                  Automatically email receipts after payment
                </p>
              </div>
              <Switch
                checked={formData.autoSendReceipts}
                onCheckedChange={checked => handleInputChange('autoSendReceipts', checked)}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="receiptFooterText">Receipt Footer Text</Label>
            <Textarea
              id="receiptFooterText"
              value={formData.receiptFooterText}
              onChange={e => handleInputChange('receiptFooterText', e.target.value)}
              placeholder="Thank you for your payment!"
              rows={2}
              maxLength={500}
            />
            <p className="text-xs text-muted-foreground">
              {formData.receiptFooterText.length}/500 characters
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Tax Settings */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <DollarSign className="h-5 w-5" />
            Tax Settings
          </CardTitle>
          <CardDescription>
            Configure sales tax for your invoices
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Enable Tax</Label>
              <p className="text-sm text-muted-foreground">
                Apply tax to invoice line items
              </p>
            </div>
            <Switch
              checked={formData.enableTax}
              onCheckedChange={checked => handleInputChange('enableTax', checked)}
            />
          </div>

          {formData.enableTax && (
            <div className="grid gap-6 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="taxLabel">Tax Label</Label>
                <Input
                  id="taxLabel"
                  value={formData.taxLabel}
                  onChange={e => handleInputChange('taxLabel', e.target.value)}
                  placeholder="Sales Tax"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="taxRate">Tax Rate (%)</Label>
                <Input
                  id="taxRate"
                  type="number"
                  min={0}
                  max={100}
                  step={0.01}
                  value={formData.taxRate}
                  onChange={e => handleInputChange('taxRate', parseFloat(e.target.value) || 0)}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Payment Methods */}
      <Card>
        <CardHeader>
          <CardTitle>Accepted Payment Methods</CardTitle>
          <CardDescription>
            Select which payment methods your practice accepts
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {(Object.keys(paymentMethodLabels) as PaymentMethod[]).map(method => (
              <div key={method} className="flex items-center space-x-3">
                <Checkbox
                  id={method}
                  checked={formData.acceptedPaymentMethods.includes(method)}
                  onCheckedChange={() => handlePaymentMethodToggle(method)}
                />
                <Label htmlFor={method} className="cursor-pointer">
                  {paymentMethodLabels[method]}
                </Label>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Late Fee Settings */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Clock className="h-5 w-5" />
            Late Fee Settings
          </CardTitle>
          <CardDescription>
            Configure automatic late fees for overdue invoices
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Enable Late Fees</Label>
              <p className="text-sm text-muted-foreground">
                Automatically apply late fees to overdue invoices
              </p>
            </div>
            <Switch
              checked={formData.lateFeeEnabled}
              onCheckedChange={checked => handleInputChange('lateFeeEnabled', checked)}
            />
          </div>

          {formData.lateFeeEnabled && (
            <>
              <div className="rounded-md bg-yellow-50 dark:bg-yellow-900/20 p-4 flex gap-3">
                <AlertTriangle className="h-5 w-5 text-yellow-600 dark:text-yellow-500 flex-shrink-0 mt-0.5" />
                <div className="text-sm text-yellow-800 dark:text-yellow-200">
                  Late fees will be automatically calculated and added to overdue invoices 
                  after the grace period expires.
                </div>
              </div>

              <div className="grid gap-6 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="lateFeeGracePeriod">Grace Period (days)</Label>
                  <Input
                    id="lateFeeGracePeriod"
                    type="number"
                    min={0}
                    max={365}
                    value={formData.lateFeeGracePeriod}
                    onChange={e => handleInputChange('lateFeeGracePeriod', parseInt(e.target.value) || 0)}
                  />
                  <p className="text-xs text-muted-foreground">
                    Days after due date before late fee applies
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="lateFeePercentage">Late Fee Rate (%)</Label>
                  <Input
                    id="lateFeePercentage"
                    type="number"
                    min={0}
                    max={100}
                    step={0.1}
                    value={formData.lateFeePercentage}
                    onChange={e => handleInputChange('lateFeePercentage', parseFloat(e.target.value) || 0)}
                  />
                  <p className="text-xs text-muted-foreground">
                    Percentage of outstanding balance
                  </p>
                </div>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={isSaving} className="gap-2">
          {isSaving ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Save className="h-4 w-4" />
          )}
          Save Preferences
        </Button>
      </div>
    </div>
  );
}

// ============================================
// CoreDent PMS - Chairs/Operatories Tab
// Configure dental chairs and treatment rooms
// ============================================

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Armchair, Plus, Pencil, Trash2, Loader2, Save } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { z } from 'zod';
import type { Chair } from '@/types/clinic';
import { clinicApi } from '@/services/clinicApi';

const chairSchema = z.object({
  name: z.string().trim().min(1, 'Chair name is required').max(50),
  description: z.string().max(200).optional(),
  color: z.string().regex(/^#[0-9A-Fa-f]{6}$/, 'Please select a valid color'),
});

interface ChairsTabProps {
  chairs: Chair[];
  onUpdate: (chairs: Chair[]) => void;
}

const PRESET_COLORS = [
  '#3B82F6', '#10B981', '#8B5CF6', '#F59E0B', '#EF4444',
  '#EC4899', '#6366F1', '#14B8A6', '#F97316', '#84CC16',
];

export function ChairsTab({ chairs, onUpdate }: ChairsTabProps) {
  const [chairList, setChairList] = useState<Chair[]>([...chairs]);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingChair, setEditingChair] = useState<Chair | null>(null);
  const [formData, setFormData] = useState({ name: '', description: '', color: '#3B82F6' });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const { toast } = useToast();

  const openAddDialog = () => {
    setEditingChair(null);
    setFormData({ name: '', description: '', color: '#3B82F6' });
    setErrors({});
    setIsDialogOpen(true);
  };

  const openEditDialog = (chair: Chair) => {
    setEditingChair(chair);
    setFormData({
      name: chair.name,
      description: chair.description || '',
      color: chair.color,
    });
    setErrors({});
    setIsDialogOpen(true);
  };

  const handleSubmit = () => {
    setErrors({});

    const result = chairSchema.safeParse(formData);
    if (!result.success) {
      const fieldErrors: Record<string, string> = {};
      result.error.issues.forEach((issue) => {
        fieldErrors[issue.path[0] as string] = issue.message;
      });
      setErrors(fieldErrors);
      return;
    }

    if (editingChair) {
      // Update existing chair
      setChairList(prev =>
        prev.map(c =>
          c.id === editingChair.id
            ? { ...c, name: formData.name, description: formData.description, color: formData.color }
            : c
        )
      );
      toast({ title: 'Chair Updated', description: `${formData.name} has been updated.` });
    } else {
      // Add new chair
      const newChair: Chair = {
        id: Date.now().toString(),
        name: formData.name,
        description: formData.description,
        color: formData.color,
        isActive: true,
      };
      setChairList(prev => [...prev, newChair]);
      toast({ title: 'Chair Added', description: `${formData.name} has been added.` });
    }

    setIsDialogOpen(false);
  };

  const toggleChairStatus = (id: string) => {
    setChairList(prev =>
      prev.map(c => (c.id === id ? { ...c, isActive: !c.isActive } : c))
    );
  };

  const deleteChair = (id: string) => {
    const chair = chairList.find(c => c.id === id);
    setChairList(prev => prev.filter(c => c.id !== id));
    toast({
      title: 'Chair Deleted',
      description: `${chair?.name} has been removed.`,
    });
  };

  const handleSaveAll = async () => {
    setIsSaving(true);

    try {
      const response = await clinicApi.updateSettings({ chairs: chairList });
      if (!response.success || !response.data) {
        throw new Error(response.error?.message || 'Failed to save chairs');
      }
      setChairList(response.data.chairs);
      onUpdate(response.data.chairs);
      toast({ title: 'Saved', description: 'Chair configuration has been saved.' });
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Failed to save. Please try again.',
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Armchair className="h-5 w-5" />
              Chairs & Operatories
            </CardTitle>
            <CardDescription>
              Manage your dental chairs and treatment rooms
            </CardDescription>
          </div>
          <Button onClick={openAddDialog} className="gap-2">
            <Plus className="h-4 w-4" />
            Add Chair
          </Button>
        </CardHeader>
        <CardContent>
          {chairList.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Armchair className="h-12 w-12 text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No chairs configured</h3>
              <p className="text-muted-foreground">Add your first operatory to get started</p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Chair</TableHead>
                  <TableHead>Description</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="w-[100px]">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {chairList.map((chair) => (
                  <TableRow key={chair.id}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <div
                          className="h-4 w-4 rounded-full"
                          style={{ backgroundColor: chair.color }}
                        />
                        <span className="font-medium">{chair.name}</span>
                      </div>
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {chair.description || '—'}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={chair.isActive}
                          onCheckedChange={() => toggleChairStatus(chair.id)}
                        />
                        <Badge variant={chair.isActive ? 'default' : 'secondary'}>
                          {chair.isActive ? 'Active' : 'Inactive'}
                        </Badge>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-1">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => openEditDialog(chair)}
                        >
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="text-destructive"
                          onClick={() => deleteChair(chair.id)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSaveAll} disabled={isSaving} size="lg" className="gap-2">
          {isSaving ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              Save Chairs
            </>
          )}
        </Button>
      </div>

      {/* Add/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {editingChair ? 'Edit Chair' : 'Add New Chair'}
            </DialogTitle>
            <DialogDescription>
              Configure the operatory details
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="chairName">Name *</Label>
              <Input
                id="chairName"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className={errors.name ? 'border-destructive' : ''}
                placeholder="Operatory 1"
              />
              {errors.name && (
                <p className="text-sm text-destructive">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="chairDescription">Description</Label>
              <Input
                id="chairDescription"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Main treatment room"
              />
            </div>

            <div className="space-y-2">
              <Label>Color</Label>
              <div className="flex flex-wrap gap-2">
                {PRESET_COLORS.map((color) => (
                  <button
                    key={color}
                    type="button"
                    className={`h-8 w-8 rounded-full border-2 transition-all ${
                      formData.color === color
                        ? 'border-foreground scale-110'
                        : 'border-transparent'
                    }`}
                    style={{ backgroundColor: color }}
                    onClick={() => setFormData({ ...formData, color })}
                  />
                ))}
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit}>
              {editingChair ? 'Update' : 'Add'} Chair
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ============================================
// CoreDent PMS - Confirmation Dialog
// Reusable confirmation prompt with variants
// ============================================

import React, { useState } from 'react';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Loader2, AlertTriangle, Trash2, UserX, Ban } from 'lucide-react';

type ConfirmationType = 'danger' | 'warning' | 'deactivate' | 'delete';

interface ConfirmationDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: string;
  type?: ConfirmationType;
  confirmText?: string;
  cancelText?: string;
  requireTypedConfirmation?: string;
  onConfirm: () => Promise<void> | void;
  isLoading?: boolean;
}

const typeConfig: Record<ConfirmationType, { icon: React.ElementType; buttonClass: string }> = {
  danger: {
    icon: AlertTriangle,
    buttonClass: 'bg-destructive text-destructive-foreground hover:bg-destructive/90',
  },
  warning: {
    icon: AlertTriangle,
    buttonClass: 'bg-yellow-600 text-white hover:bg-yellow-700',
  },
  deactivate: {
    icon: UserX,
    buttonClass: 'bg-orange-600 text-white hover:bg-orange-700',
  },
  delete: {
    icon: Trash2,
    buttonClass: 'bg-destructive text-destructive-foreground hover:bg-destructive/90',
  },
};

export function ConfirmationDialog({
  open,
  onOpenChange,
  title,
  description,
  type = 'danger',
  confirmText = 'Confirm',
  cancelText = 'Cancel',
  requireTypedConfirmation,
  onConfirm,
  isLoading = false,
}: ConfirmationDialogProps) {
  const [typedValue, setTypedValue] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const config = typeConfig[type];
  const Icon = config.icon;

  const canConfirm = requireTypedConfirmation
    ? typedValue.toLowerCase() === requireTypedConfirmation.toLowerCase()
    : true;

  const handleConfirm = async () => {
    try {
      setIsSubmitting(true);
      await onConfirm();
      onOpenChange(false);
      setTypedValue('');
    } catch (error) {
      // Error handling should be done by the parent
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      setTypedValue('');
    }
    onOpenChange(open);
  };

  return (
    <AlertDialog open={open} onOpenChange={handleOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <div className="flex items-center gap-3">
            <div className={`flex h-10 w-10 items-center justify-center rounded-full ${
              type === 'warning' ? 'bg-yellow-100 dark:bg-yellow-900/30' : 'bg-destructive/10'
            }`}>
              <Icon className={`h-5 w-5 ${
                type === 'warning' ? 'text-yellow-600 dark:text-yellow-500' : 'text-destructive'
              }`} />
            </div>
            <AlertDialogTitle>{title}</AlertDialogTitle>
          </div>
          <AlertDialogDescription className="pt-2">
            {description}
          </AlertDialogDescription>
        </AlertDialogHeader>

        {requireTypedConfirmation && (
          <div className="space-y-2 py-4">
            <Label htmlFor="confirmation">
              Type <span className="font-mono font-bold">{requireTypedConfirmation}</span> to confirm
            </Label>
            <Input
              id="confirmation"
              value={typedValue}
              onChange={e => setTypedValue(e.target.value)}
              placeholder={requireTypedConfirmation}
              autoComplete="off"
            />
          </div>
        )}

        <AlertDialogFooter>
          <AlertDialogCancel disabled={isSubmitting || isLoading}>
            {cancelText}
          </AlertDialogCancel>
          <AlertDialogAction
            onClick={handleConfirm}
            disabled={!canConfirm || isSubmitting || isLoading}
            className={config.buttonClass}
          >
            {(isSubmitting || isLoading) && (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            )}
            {confirmText}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

// ============================================
// CoreDent PMS - General Settings Tab
// Clinic name, logo, contact, and address
// ============================================

import React, { useState, useRef } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Loader2, Upload, Save, Building2, MapPin, Phone, Globe } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { z } from 'zod';
import type { ClinicSettings } from '@/types/clinic';
import { US_STATES } from '@/types/clinic';
import { clinicApi } from '@/services/clinicApi';

const generalSettingsSchema = z.object({
  name: z.string().trim().min(1, 'Clinic name is required').max(100),
  email: z.string().trim().email('Please enter a valid email'),
  phone: z.string().trim().min(10, 'Please enter a valid phone number'),
  fax: z.string().optional(),
  website: z.string().url('Please enter a valid URL').optional().or(z.literal('')),
  address: z.object({
    street: z.string().trim().min(1, 'Street address is required'),
    suite: z.string().optional(),
    city: z.string().trim().min(1, 'City is required'),
    state: z.string().min(2, 'State is required'),
    zipCode: z.string().regex(/^\d{5}(-\d{4})?$/, 'Please enter a valid ZIP code'),
    country: z.string().default('USA'),
  }),
});

interface GeneralSettingsTabProps {
  settings: ClinicSettings;
  onUpdate: (updates: Partial<ClinicSettings>) => void;
}

export function GeneralSettingsTab({ settings, onUpdate }: GeneralSettingsTabProps) {
  const [formData, setFormData] = useState({
    name: settings.name,
    email: settings.email,
    phone: settings.phone,
    fax: settings.fax || '',
    website: settings.website || '',
    address: { ...settings.address },
  });
  const [logoPreview, setLogoPreview] = useState<string | undefined>(settings.logoUrl);
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  const handleInputChange = (field: string, value: string) => {
    if (field.startsWith('address.')) {
      const addressField = field.replace('address.', '');
      setFormData(prev => ({
        ...prev,
        address: { ...prev.address, [addressField]: value },
      }));
    } else {
      setFormData(prev => ({ ...prev, [field]: value }));
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type and size
    if (!file.type.startsWith('image/')) {
      toast({
        variant: 'destructive',
        title: 'Invalid file type',
        description: 'Please upload an image file (PNG, JPG, etc.)',
      });
      return;
    }

    if (file.size > 2 * 1024 * 1024) {
      toast({
        variant: 'destructive',
        title: 'File too large',
        description: 'Logo must be less than 2MB',
      });
      return;
    }

    setLogoFile(file);
    const reader = new FileReader();
    reader.onload = () => {
      setLogoPreview(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    setErrors({});

    // Validate form data
    const result = generalSettingsSchema.safeParse(formData);

    if (!result.success) {
      const fieldErrors: Record<string, string> = {};
      result.error.issues.forEach((issue) => {
        const path = issue.path.join('.');
        fieldErrors[path] = issue.message;
      });
      setErrors(fieldErrors);
      return;
    }

    setIsSaving(true);

    try {
      let logoUrl = logoPreview;
      if (logoFile) {
        const uploadResponse = await clinicApi.uploadLogo(logoFile);
        if (!uploadResponse.success || !uploadResponse.data) {
          throw new Error(uploadResponse.error?.message || 'Logo upload failed');
        }
        logoUrl = uploadResponse.data.url;
      }

      const response = await clinicApi.updateSettings({ ...formData, logoUrl });
      if (!response.success || !response.data) {
        throw new Error(response.error?.message || 'Failed to save settings');
      }

      onUpdate(response.data);
      setLogoFile(null);

      toast({
        title: 'Settings Saved',
        description: 'Your clinic settings have been updated.',
      });
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Failed to save settings. Please try again.',
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Clinic Identity */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Building2 className="h-5 w-5" />
            Clinic Identity
          </CardTitle>
          <CardDescription>
            Your practice name and logo
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Logo Upload */}
          <div className="flex items-center gap-6">
            <Avatar className="h-24 w-24">
              <AvatarImage src={logoPreview} alt="Clinic logo" />
              <AvatarFallback className="bg-primary text-primary-foreground text-2xl">
                {formData.name?.charAt(0) || '?'}
              </AvatarFallback>
            </Avatar>
            <div className="space-y-2">
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleLogoUpload}
                className="hidden"
              />
              <Button
                type="button"
                variant="outline"
                onClick={() => fileInputRef.current?.click()}
              >
                <Upload className="mr-2 h-4 w-4" />
                Upload Logo
              </Button>
              <p className="text-xs text-muted-foreground">
                PNG, JPG up to 2MB. Recommended: 200x200px
              </p>
            </div>
          </div>

          {/* Clinic Name */}
          <div className="space-y-2">
            <Label htmlFor="name">Clinic Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => handleInputChange('name', e.target.value)}
              className={errors.name ? 'border-destructive' : ''}
              placeholder="Bright Smile Dental"
            />
            {errors.name && (
              <p className="text-sm text-destructive">{errors.name}</p>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Contact Information */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Phone className="h-5 w-5" />
            Contact Information
          </CardTitle>
          <CardDescription>
            How patients can reach your practice
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="email">Email *</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => handleInputChange('email', e.target.value)}
                className={errors.email ? 'border-destructive' : ''}
                placeholder="info@clinic.com"
              />
              {errors.email && (
                <p className="text-sm text-destructive">{errors.email}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="phone">Phone *</Label>
              <Input
                id="phone"
                type="tel"
                value={formData.phone}
                onChange={(e) => handleInputChange('phone', e.target.value)}
                className={errors.phone ? 'border-destructive' : ''}
                placeholder="(555) 123-4567"
              />
              {errors.phone && (
                <p className="text-sm text-destructive">{errors.phone}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="fax">Fax</Label>
              <Input
                id="fax"
                type="tel"
                value={formData.fax}
                onChange={(e) => handleInputChange('fax', e.target.value)}
                placeholder="(555) 123-4568"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="website">Website</Label>
              <Input
                id="website"
                type="url"
                value={formData.website}
                onChange={(e) => handleInputChange('website', e.target.value)}
                className={errors.website ? 'border-destructive' : ''}
                placeholder="https://yourpractice.com"
              />
              {errors.website && (
                <p className="text-sm text-destructive">{errors.website}</p>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Address */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <MapPin className="h-5 w-5" />
            Practice Address
          </CardTitle>
          <CardDescription>
            Your clinic's physical location
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="street">Street Address *</Label>
                <Input
                  id="street"
                  value={formData.address.street}
                  onChange={(e) => handleInputChange('address.street', e.target.value)}
                  className={errors['address.street'] ? 'border-destructive' : ''}
                  placeholder="123 Main Street"
                />
                {errors['address.street'] && (
                  <p className="text-sm text-destructive">{errors['address.street']}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="suite">Suite / Unit</Label>
                <Input
                  id="suite"
                  value={formData.address.suite}
                  onChange={(e) => handleInputChange('address.suite', e.target.value)}
                  placeholder="Suite 200"
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-3">
              <div className="space-y-2">
                <Label htmlFor="city">City *</Label>
                <Input
                  id="city"
                  value={formData.address.city}
                  onChange={(e) => handleInputChange('address.city', e.target.value)}
                  className={errors['address.city'] ? 'border-destructive' : ''}
                  placeholder="Los Angeles"
                />
                {errors['address.city'] && (
                  <p className="text-sm text-destructive">{errors['address.city']}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="state">State *</Label>
                <Select
                  value={formData.address.state}
                  onValueChange={(value) => handleInputChange('address.state', value)}
                >
                  <SelectTrigger className={errors['address.state'] ? 'border-destructive' : ''}>
                    <SelectValue placeholder="Select state" />
                  </SelectTrigger>
                  <SelectContent>
                    {US_STATES.map((state) => (
                      <SelectItem key={state.code} value={state.code}>
                        {state.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {errors['address.state'] && (
                  <p className="text-sm text-destructive">{errors['address.state']}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="zipCode">ZIP Code *</Label>
                <Input
                  id="zipCode"
                  value={formData.address.zipCode}
                  onChange={(e) => handleInputChange('address.zipCode', e.target.value)}
                  className={errors['address.zipCode'] ? 'border-destructive' : ''}
                  placeholder="90001"
                />
                {errors['address.zipCode'] && (
                  <p className="text-sm text-destructive">{errors['address.zipCode']}</p>
                )}
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={isSaving} size="lg" className="gap-2">
          {isSaving ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              Save Changes
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

// ============================================
// CoreDent PMS - Working Hours Tab
// Configure clinic working days and hours
// ============================================

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2, Save, Clock, Copy } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import type { WorkingHours, DaySchedule } from '@/types/clinic';
import { clinicApi } from '@/services/clinicApi';

interface WorkingHoursTabProps {
  workingHours: WorkingHours;
  onUpdate: (workingHours: WorkingHours) => void;
}

type DayKey = keyof WorkingHours;

const DAYS: { key: DayKey; label: string }[] = [
  { key: 'monday', label: 'Monday' },
  { key: 'tuesday', label: 'Tuesday' },
  { key: 'wednesday', label: 'Wednesday' },
  { key: 'thursday', label: 'Thursday' },
  { key: 'friday', label: 'Friday' },
  { key: 'saturday', label: 'Saturday' },
  { key: 'sunday', label: 'Sunday' },
];

// Generate time options in 15-minute increments
const generateTimeOptions = () => {
  const options: string[] = [];
  for (let hour = 0; hour < 24; hour++) {
    for (let minute = 0; minute < 60; minute += 15) {
      const h = hour.toString().padStart(2, '0');
      const m = minute.toString().padStart(2, '0');
      options.push(`${h}:${m}`);
    }
  }
  return options;
};

const TIME_OPTIONS = generateTimeOptions();

const formatTime = (time: string) => {
  const [hours, minutes] = time.split(':');
  const hour = parseInt(hours);
  const ampm = hour >= 12 ? 'PM' : 'AM';
  const displayHour = hour % 12 || 12;
  return `${displayHour}:${minutes} ${ampm}`;
};

export function WorkingHoursTab({ workingHours, onUpdate }: WorkingHoursTabProps) {
  const [hours, setHours] = useState<WorkingHours>({ ...workingHours });
  const [isSaving, setIsSaving] = useState(false);
  const { toast } = useToast();

  const handleDayChange = (day: DayKey, field: keyof DaySchedule, value: string | boolean) => {
    setHours(prev => ({
      ...prev,
      [day]: {
        ...prev[day],
        [field]: value,
      },
    }));
  };

  const copyToAllWeekdays = (sourceDay: DayKey) => {
    const sourceSchedule = hours[sourceDay];
    const weekdays: DayKey[] = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'];

    setHours(prev => {
      const updated = { ...prev };
      weekdays.forEach(day => {
        updated[day] = { ...sourceSchedule };
      });
      return updated;
    });

    toast({
      title: 'Schedule Copied',
      description: 'Applied to all weekdays (Mon-Fri)',
    });
  };

  const handleSave = async () => {
    setIsSaving(true);

    try {
      const response = await clinicApi.updateSettings({ workingHours: hours });
      if (!response.success || !response.data) {
        throw new Error(response.error?.message || 'Failed to save hours');
      }
      onUpdate(response.data.workingHours);

      toast({
        title: 'Hours Saved',
        description: 'Working hours have been updated.',
      });
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Failed to save hours. Please try again.',
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Clock className="h-5 w-5" />
            Working Hours
          </CardTitle>
          <CardDescription>
            Set your clinic's operating hours for each day of the week
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {DAYS.map(({ key, label }) => (
              <div
                key={key}
                className={`flex flex-col sm:flex-row sm:items-center gap-4 p-4 rounded-lg border ${
                  hours[key].isOpen ? 'bg-card' : 'bg-muted/50'
                }`}
              >
                {/* Day Name & Toggle */}
                <div className="flex items-center justify-between sm:w-32">
                  <Label className="font-medium">{label}</Label>
                  <Switch
                    checked={hours[key].isOpen}
                    onCheckedChange={(checked) => handleDayChange(key, 'isOpen', checked)}
                  />
                </div>

                {/* Time Selectors */}
                {hours[key].isOpen ? (
                  <div className="flex flex-1 flex-wrap items-center gap-4">
                    <div className="flex items-center gap-2">
                      <Label className="text-sm text-muted-foreground">Open</Label>
                      <Select
                        value={hours[key].openTime}
                        onValueChange={(value) => handleDayChange(key, 'openTime', value)}
                      >
                        <SelectTrigger className="w-[110px]">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {TIME_OPTIONS.map((time) => (
                            <SelectItem key={time} value={time}>
                              {formatTime(time)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <span className="text-muted-foreground">to</span>

                    <div className="flex items-center gap-2">
                      <Label className="text-sm text-muted-foreground">Close</Label>
                      <Select
                        value={hours[key].closeTime}
                        onValueChange={(value) => handleDayChange(key, 'closeTime', value)}
                      >
                        <SelectTrigger className="w-[110px]">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {TIME_OPTIONS.map((time) => (
                            <SelectItem key={time} value={time}>
                              {formatTime(time)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Copy to All Button (show only for weekdays) */}
                    {['monday', 'tuesday', 'wednesday', 'thursday', 'friday'].includes(key) && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => copyToAllWeekdays(key)}
                        className="gap-1 text-xs"
                      >
                        <Copy className="h-3 w-3" />
                        Apply to weekdays
                      </Button>
                    )}
                  </div>
                ) : (
                  <div className="flex-1 text-sm text-muted-foreground">
                    Closed
                  </div>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={isSaving} size="lg" className="gap-2">
          {isSaving ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              Save Hours
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

