import * as React from "react";

import type { ToastActionElement, ToastProps } from "@/components/ui/toast";

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType["ADD_TOAST"];
      toast: ToasterToast;
    }
  | {
      type: ActionType["UPDATE_TOAST"];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType["DISMISS_TOAST"];
      toastId?: ToasterToast["id"];
    }
  | {
      type: ActionType["REMOVE_TOAST"];
      toastId?: ToasterToast["id"];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case "DISMISS_TOAST": {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      };
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, "id">;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id });

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id: id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, [state]);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  };
}

export { useToast, toast };

import { useState, useCallback } from 'react';
import { useToast } from '@/hooks/use-toast';
import type { ApiResponse } from '@/types/api';
import { logger } from '@/lib/logger';

interface UseApiRequestOptions<T> {
  onSuccess?: (data: T) => void;
  onError?: (error: any) => void;
  successMessage?: string;
  errorMessage?: string;
}

/**
 * Standard hook for managing API requests with loading, error, and toast notifications.
 */
export function useApiRequest<T>(
  apiFunc: (...args: any[]) => Promise<ApiResponse<T>>,
  options: UseApiRequestOptions<T> = {}
) {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { toast } = useToast();

  const execute = useCallback(
    async (...args: any[]) => {
      setIsLoading(true);
      setError(null);

      try {
        const response = await apiFunc(...args);

        // Check for success - data can be null/undefined for valid empty responses
        if (response.success) {
          setData(response.data || null);
          if (options.successMessage) {
            toast({
              title: 'Success',
              description: options.successMessage,
            });
          }
          options.onSuccess?.(response.data!);
          return response.data || null;
        } else {
          const message = response.error?.message || options.errorMessage || 'An error occurred';
          logger.error('API request failed', undefined, { message, error: response.error });
          setError(message);
          toast({
            variant: 'destructive',
            title: 'Error',
            description: message,
          });
          options.onError?.(response.error);
          return null;
        }
      } catch (err) {
        const message = options.errorMessage || 'Network error occurred';
        setError(message);
        logger.error('API request hook failed', err as Error);
        toast({
          variant: 'destructive',
          title: 'Error',
          description: message,
        });
        options.onError?.(err);
        return null;
      } finally {
        setIsLoading(false);
      }
    },
    [apiFunc, options, toast]
  );

  return {
    data,
    setData,
    isLoading,
    error,
    execute,
  };
}

import { useState, useCallback, useMemo } from 'react';
import { subDays, subMonths, startOfMonth, endOfMonth } from 'date-fns';
import type { DateRange } from '@/types/reports';

export type PresetRange = 'last7days' | 'last30days' | 'thisMonth' | 'lastMonth' | 'last3months' | 'custom';

export const PRESET_RANGES: { value: PresetRange; label: string }[] = [
  { value: 'last7days', label: 'Last 7 Days' },
  { value: 'last30days', label: 'Last 30 Days' },
  { value: 'thisMonth', label: 'This Month' },
  { value: 'lastMonth', label: 'Last Month' },
  { value: 'last3months', label: 'Last 3 Months' },
];

export function getDateRangeFromPreset(preset: PresetRange): DateRange {
  const today = new Date();
  switch (preset) {
    case 'last7days':
      return { from: subDays(today, 7), to: today };
    case 'last30days':
      return { from: subDays(today, 30), to: today };
    case 'thisMonth':
      return { from: startOfMonth(today), to: today };
    case 'lastMonth': {
      const lastMonth = subMonths(today, 1);
      return { from: startOfMonth(lastMonth), to: endOfMonth(lastMonth) };
    }
    case 'last3months':
      return { from: subMonths(today, 3), to: today };
    default:
      return { from: subDays(today, 30), to: today };
  }
}

/**
 * Hook for managing date range selection and presets.
 */
export function useDateRange(initialPreset: PresetRange = 'last30days') {
  const [selectedPreset, setSelectedPreset] = useState<PresetRange>(initialPreset);
  const [dateRange, setDateRange] = useState<DateRange>(() => getDateRangeFromPreset(initialPreset));

  const handlePresetChange = useCallback((preset: PresetRange) => {
    setSelectedPreset(preset);
    if (preset !== 'custom') {
      setDateRange(getDateRangeFromPreset(preset));
    }
  }, []);

  const setCustomRange = useCallback((range: DateRange) => {
    setDateRange(range);
    setSelectedPreset('custom');
  }, []);

  // Memoize dateRange to prevent unnecessary re-renders
  const memoizedDateRange = useMemo(() => dateRange, [dateRange.from, dateRange.to]);

  return {
    dateRange: memoizedDateRange,
    selectedPreset,
    handlePresetChange,
    setCustomRange,
    PRESET_RANGES,
  };
}

/**
 * Generic Form Validation Hook
 * Eliminates duplication across form validation logic
 * Provides standardized validation, error handling, and state management
 */

import { useState, useCallback } from 'react';
import type { FormStateType } from '@/types/state';
import type { FormFieldError } from '@/types/forms';

// ============================================
// Validation Types
// ============================================

/**
 * Validation rule for a field
 */
export type ValidationRule<T = unknown> = {
  validate: (value: T) => boolean | string;
  message?: string;
};

/**
 * Validation schema for a form
 */
export type ValidationSchema<T extends Record<string, unknown>> = {
  [K in keyof T]?: ValidationRule<T[K]>[];
};

/**
 * Form validation result
 */
export interface ValidationResult {
  isValid: boolean;
  errors: Record<string, string>;
}

// ============================================
// Validation Functions
// ============================================

/**
 * Common validation rules
 */
export const validators = {
  /**
   * Required field validator
   */
  required: (message = 'This field is required'): ValidationRule => ({
    validate: (value: unknown) => {
      if (typeof value === 'string') return value.trim().length > 0;
      if (Array.isArray(value)) return value.length > 0;
      return value !== null && value !== undefined;
    },
    message,
  }),

  /**
   * Email validator
   */
  email: (message = 'Invalid email address'): ValidationRule => ({
    validate: (value: unknown) => {
      if (typeof value !== 'string') return false;
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(value);
    },
    message,
  }),

  /**
   * Minimum length validator
   */
  minLength: (min: number, message?: string): ValidationRule => ({
    validate: (value: unknown) => {
      if (typeof value === 'string') return value.length >= min;
      if (Array.isArray(value)) return value.length >= min;
      return false;
    },
    message: message || `Minimum length is ${min}`,
  }),

  /**
   * Maximum length validator
   */
  maxLength: (max: number, message?: string): ValidationRule => ({
    validate: (value: unknown) => {
      if (typeof value === 'string') return value.length <= max;
      if (Array.isArray(value)) return value.length <= max;
      return false;
    },
    message: message || `Maximum length is ${max}`,
  }),

  /**
   * Pattern validator
   */
  pattern: (pattern: RegExp, message = 'Invalid format'): ValidationRule => ({
    validate: (value: unknown) => {
      if (typeof value !== 'string') return false;
      return pattern.test(value);
    },
    message,
  }),

  /**
   * Number range validator
   */
  range: (min: number, max: number, message?: string): ValidationRule => ({
    validate: (value: unknown) => {
      if (typeof value !== 'number') return false;
      return value >= min && value <= max;
    },
    message: message || `Value must be between ${min} and ${max}`,
  }),

  /**
   * Custom validator
   */
  custom: (validate: (value: unknown) => boolean, message = 'Invalid value'): ValidationRule => ({
    validate,
    message,
  }),
};

// ============================================
// Validation Hook
// ============================================

/**
 * Generic form validation hook
 * Replaces 10+ similar validation hooks
 *
 * @example
 * const { values, errors, touched, handleChange, handleBlur, validate } = useFormValidation(
 *   { name: '', email: '' },
 *   {
 *     name: [validators.required(), validators.minLength(2)],
 *     email: [validators.required(), validators.email()],
 *   }
 * );
 */
export function useFormValidation<T extends Record<string, unknown>>(
  initialValues: T,
  schema?: ValidationSchema<T>,
  options?: {
    validateOnChange?: boolean;
    validateOnBlur?: boolean;
  }
) {
  const { validateOnChange = false, validateOnBlur = true } = options || {};

  const [values, setValues] = useState<T>(initialValues);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  /**
   * Validate a single field
   */
  const validateField = useCallback(
    (fieldName: keyof T, value: unknown): string | undefined => {
      const rules = schema?.[fieldName];
      if (!rules) return undefined;

      for (const rule of rules) {
        const result = rule.validate(value);
        if (result !== true) {
          return typeof result === 'string' ? result : rule.message || 'Invalid value';
        }
      }

      return undefined;
    },
    [schema]
  );

  /**
   * Validate all fields
   */
  const validate = useCallback((): ValidationResult => {
    const newErrors: Record<string, string> = {};
    let isValid = true;

    Object.keys(values).forEach((fieldName) => {
      const error = validateField(fieldName as keyof T, values[fieldName as keyof T]);
      if (error) {
        newErrors[fieldName] = error;
        isValid = false;
      }
    });

    setErrors(newErrors);
    return { isValid, errors: newErrors };
  }, [values, validateField]);

  /**
   * Handle field change
   */
  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
      const { name, value, type } = e.target;
      const fieldValue = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;

      setValues((prev) => ({
        ...prev,
        [name]: fieldValue,
      }));

      if (validateOnChange) {
        const error = validateField(name as keyof T, fieldValue);
        setErrors((prev) => ({
          ...prev,
          [name]: error || '',
        }));
      }
    },
    [validateOnChange, validateField]
  );

  /**
   * Handle field blur
   */
  const handleBlur = useCallback(
    (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
      const { name } = e.target;

      setTouched((prev) => ({
        ...prev,
        [name]: true,
      }));

      if (validateOnBlur) {
        const error = validateField(name as keyof T, values[name as keyof T]);
        setErrors((prev) => ({
          ...prev,
          [name]: error || '',
        }));
      }
    },
    [validateOnBlur, validateField, values]
  );

  /**
   * Handle form submission
   */
  const handleSubmit = useCallback(
    async (onSubmit: (values: T) => void | Promise<void>) => {
      return async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();

        const { isValid } = validate();
        if (!isValid) return;

        setIsSubmitting(true);
        try {
          await onSubmit(values);
        } finally {
          setIsSubmitting(false);
        }
      };
    },
    [validate, values]
  );

  /**
   * Reset form to initial values
   */
  const reset = useCallback(() => {
    setValues(initialValues);
    setErrors({});
    setTouched({});
  }, [initialValues]);

  /**
   * Set field value programmatically
   */
  const setFieldValue = useCallback((fieldName: keyof T, value: unknown) => {
    setValues((prev) => ({
      ...prev,
      [fieldName]: value,
    }));
  }, []);

  /**
   * Set field error programmatically
   */
  const setFieldError = useCallback((fieldName: string, error: string) => {
    setErrors((prev) => ({
      ...prev,
      [fieldName]: error,
    }));
  }, []);

  /**
   * Get form state
   */
  const getFormState = useCallback((): FormStateType => {
    const isDirty = JSON.stringify(values) !== JSON.stringify(initialValues);
    const isValid = Object.keys(errors).length === 0;

    return {
      isSubmitting,
      isValid,
      isDirty,
      errors,
      touched,
    };
  }, [values, initialValues, errors, touched, isSubmitting]);

  return {
    values,
    errors,
    touched,
    isSubmitting,
    handleChange,
    handleBlur,
    handleSubmit,
    validate,
    reset,
    setFieldValue,
    setFieldError,
    getFormState,
  };
}

/**
 * Hook for validating a single field
 * Useful for inline validation
 *
 * @example
 * const { error, validate } = useFieldValidation(
 *   'email',
 *   [validators.required(), validators.email()]
 * );
 */
export function useFieldValidation(
  fieldName: string,
  rules?: ValidationRule[],
  options?: {
    validateOnChange?: boolean;
  }
) {
  const { validateOnChange = false } = options || {};
  const [value, setValue] = useState('');
  const [error, setError] = useState<string | undefined>();

  const validate = useCallback(
    (val: unknown): string | undefined => {
      if (!rules) return undefined;

      for (const rule of rules) {
        const result = rule.validate(val);
        if (result !== true) {
          return typeof result === 'string' ? result : rule.message || 'Invalid value';
        }
      }

      return undefined;
    },
    [rules]
  );

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      const newValue = e.target.value;
      setValue(newValue);

      if (validateOnChange) {
        const err = validate(newValue);
        setError(err);
      }
    },
    [validate, validateOnChange]
  );

  const handleBlur = useCallback(() => {
    const err = validate(value);
    setError(err);
  }, [validate, value]);

  return {
    value,
    error,
    setValue,
    setError,
    handleChange,
    handleBlur,
    validate,
  };
}

/**
 * Generic CRUD Hook
 * Eliminates duplication across 19+ CRUD hooks
 * Provides standardized data fetching, mutation, and state management
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useToast } from '@/hooks/use-toast';
import type { CrudService, ListParams } from '@/lib/apiServiceFactory';
import type { PaginatedResponse } from '@/types/common';
import type { AsyncCallback } from '@/types/utils';

// ============================================
// Query Key Factory
// ============================================

/**
 * Create standardized query keys for a resource
 */
export function createQueryKeys<T extends { id: string }>(resource: string) {
  return {
    all: [resource] as const,
    lists: () => [...createQueryKeys(resource).all, 'list'] as const,
    list: (params?: ListParams) => [...createQueryKeys(resource).lists(), params] as const,
    details: () => [...createQueryKeys(resource).all, 'detail'] as const,
    detail: (id: string) => [...createQueryKeys(resource).details(), id] as const,
  };
}

/**
 * Resolve resource name from service or options.
 * Prevents cache key collisions between different resource types.
 */
function resolveResourceName(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  service: any,
  resourceName?: string
): string {
  return resourceName || service?.resource || 'unknown';
}

// ============================================
// Generic List Hook
// ============================================

/**
 * Generic hook for fetching paginated lists
 * Replaces 15+ similar list hooks
 *
 * @example
 * const { data, isLoading, error } = useList(userApi, { page: 1, limit: 10 }, { resourceName: 'users' });
 */
export function useList<T extends { id: string }>(
  service: CrudService<T> | { list: (params?: ListParams) => Promise<PaginatedResponse<T>> },
  params?: ListParams,
  options?: {
    enabled?: boolean;
    staleTime?: number;
    cacheTime?: number;
    resourceName?: string;  // Required: unique per service to prevent cache collisions
  }
) {
  const resource = resolveResourceName(service, options?.resourceName);
  const queryKeys = createQueryKeys<T>(resource);

  return useQuery({
    queryKey: queryKeys.list(params),
    queryFn: () => service.list(params),
    enabled: options?.enabled !== false,
    staleTime: options?.staleTime ?? 5 * 60 * 1000, // 5 minutes
    gcTime: options?.cacheTime ?? 10 * 60 * 1000, // 10 minutes
  });
}

// ============================================
// Generic Get Hook
// ============================================

/**
 * Generic hook for fetching single item
 * Replaces 10+ similar get hooks
 *
 * @example
 * const { data, isLoading, error } = useGet(userApi, 'user-123', { resourceName: 'users' });
 */
export function useGet<T extends { id: string }>(
  service: CrudService<T> | { get: (id: string) => Promise<T | null> },
  id: string | null | undefined,
  options?: {
    enabled?: boolean;
    staleTime?: number;
    cacheTime?: number;
    resourceName?: string;  // Required: unique per service to prevent cache collisions
  }
) {
  const resource = resolveResourceName(service, options?.resourceName);
  const queryKeys = createQueryKeys<T>(resource);

  return useQuery({
    queryKey: queryKeys.detail(id || ''),
    queryFn: () => (id ? service.get(id) : Promise.resolve(null)),
    enabled: (options?.enabled !== false) && !!id,
    staleTime: options?.staleTime ?? 5 * 60 * 1000,
    gcTime: options?.cacheTime ?? 10 * 60 * 1000,
  });
}

// ============================================
// Generic Create Hook
// ============================================

/**
 * Generic hook for creating items
 * Replaces 8+ similar create hooks
 *
 * @example
 * const { mutate, isLoading } = useCreate(userApi, {
 *   resourceName: 'users',
 *   onSuccess: () => toast({ title: 'User created' })
 * });
 * mutate({ name: 'John' });
 */
export function useCreate<T extends { id: string }, CreateData = Partial<T>>(
  service: CrudService<T, CreateData> | { create: (data: CreateData) => Promise<T> },
  options?: {
    onSuccess?: AsyncCallback<T>;
    onError?: AsyncCallback<Error>;
    successMessage?: string;
    errorMessage?: string;
    resourceName?: string;  // Required: unique per service to prevent cache collisions
  }
) {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const resource = resolveResourceName(service, options?.resourceName);
  const queryKeys = createQueryKeys<T>(resource);

  return useMutation({
    mutationFn: (data: CreateData) => service.create(data),
    onSuccess: async (data) => {
      // Invalidate list queries for this resource
      await queryClient.invalidateQueries({ queryKey: queryKeys.lists() });

      if (options?.successMessage) {
        toast({ title: options.successMessage });
      }

      if (options?.onSuccess) {
        await options.onSuccess(data);
      }
    },
    onError: async (error: Error) => {
      if (options?.errorMessage) {
        toast({
          title: options.errorMessage,
          description: error.message,
          variant: 'destructive',
        });
      }

      if (options?.onError) {
        await options.onError(error);
      }
    },
  });
}

// ============================================
// Generic Update Hook
// ============================================

/**
 * Generic hook for updating items
 * Replaces 8+ similar update hooks
 *
 * @example
 * const { mutate, isLoading } = useUpdate(userApi, {
 *   resourceName: 'users',
 *   onSuccess: () => toast({ title: 'User updated' })
 * });
 * mutate({ id: 'user-123', data: { name: 'Jane' } });
 */
export function useUpdate<T extends { id: string }, UpdateData = Partial<T>>(
  service: CrudService<T, unknown, UpdateData> | { update: (id: string, data: UpdateData) => Promise<T | null> },
  options?: {
    onSuccess?: AsyncCallback<T | null>;
    onError?: AsyncCallback<Error>;
    successMessage?: string;
    errorMessage?: string;
    resourceName?: string;  // Required: unique per service to prevent cache collisions
  }
) {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const resource = resolveResourceName(service, options?.resourceName);
  const queryKeys = createQueryKeys<T>(resource);

  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: UpdateData }) => service.update(id, data),
    onSuccess: async (data, { id }) => {
      // Invalidate both list and detail queries for this resource
      await queryClient.invalidateQueries({ queryKey: queryKeys.lists() });
      await queryClient.invalidateQueries({ queryKey: queryKeys.detail(id) });

      if (options?.successMessage) {
        toast({ title: options.successMessage });
      }

      if (options?.onSuccess) {
        await options.onSuccess(data);
      }
    },
    onError: async (error: Error) => {
      if (options?.errorMessage) {
        toast({
          title: options.errorMessage,
          description: error.message,
          variant: 'destructive',
        });
      }

      if (options?.onError) {
        await options.onError(error);
      }
    },
  });
}

// ============================================
// Generic Delete Hook
// ============================================

/**
 * Generic hook for deleting items
 * Replaces 8+ similar delete hooks
 *
 * @example
 * const { mutate, isLoading } = useDelete(userApi, {
 *   resourceName: 'users',
 *   onSuccess: () => toast({ title: 'User deleted' })
 * });
 * mutate('user-123');
 */
export function useDelete<T extends { id: string }>(
  service: CrudService<T> | { delete: (id: string) => Promise<void> },
  options?: {
    onSuccess?: AsyncCallback<void>;
    onError?: AsyncCallback<Error>;
    successMessage?: string;
    errorMessage?: string;
    resourceName?: string;  // Required: unique per service to prevent cache collisions
  }
) {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const resource = resolveResourceName(service, options?.resourceName);
  const queryKeys = createQueryKeys<T>(resource);

  return useMutation({
    mutationFn: (id: string) => service.delete(id),
    onSuccess: async () => {
      // Invalidate list queries for this resource
      await queryClient.invalidateQueries({ queryKey: queryKeys.lists() });

      if (options?.successMessage) {
        toast({ title: options.successMessage });
      }

      if (options?.onSuccess) {
        await options.onSuccess();
      }
    },
    onError: async (error: Error) => {
      if (options?.errorMessage) {
        toast({
          title: options.errorMessage,
          description: error.message,
          variant: 'destructive',
        });
      }

      if (options?.onError) {
        await options.onError(error);
      }
    },
  });
}

// ============================================
// Combined CRUD Hook
// ============================================

/**
 * Combined hook for all CRUD operations
 * Useful when you need multiple operations on the same resource
 *
 * @example
 * const crud = useCrud(userApi, 'users');
 * const { data: users } = crud.useList({ page: 1 });
 * const { mutate: create } = crud.useCreate();
 * const { mutate: update } = crud.useUpdate();
 * const { mutate: remove } = crud.useDelete();
 */
export function useCrud<T extends { id: string }, CreateData = Partial<T>, UpdateData = Partial<T>>(
  service: CrudService<T, CreateData, UpdateData>,
  resourceName?: string
) {
  const resolvedName = resolveResourceName(service, resourceName);
  return {
    useList: (params?: ListParams, options?: Parameters<typeof useList>[2]) =>
      useList(service, params, { ...options, resourceName: resolvedName }),
    useGet: (id: string | null | undefined, options?: Parameters<typeof useGet>[2]) =>
      useGet(service, id, { ...options, resourceName: resolvedName }),
    useCreate: (options?: Parameters<typeof useCreate>[1]) =>
      useCreate(service, { ...options, resourceName: resolvedName }),
    useUpdate: (options?: Parameters<typeof useUpdate>[1]) =>
      useUpdate(service, { ...options, resourceName: resolvedName }),
    useDelete: (options?: Parameters<typeof useDelete>[1]) =>
      useDelete(service, { ...options, resourceName: resolvedName }),
  };
}

// Analytics Integration
// PostHog for product analytics
import { logger } from '@/lib/logger';

interface AnalyticsEvent {
  event: string;
  properties?: Record<string, unknown>;
}

interface UserProperties {
  userId?: string;
  email?: string;
  role?: string;
  practiceId?: string;
  practiceName?: string;
}

class Analytics {
  private enabled: boolean;
  private userId: string | null = null;

  constructor() {
    this.enabled = !import.meta.env.DEV && import.meta.env.VITE_ANALYTICS_ENABLED === 'true';
  }

  /**
   * Initialize analytics with user information
   */
  identify(userId: string, properties: UserProperties = {}) {
    if (!this.enabled) return;

    this.userId = userId;

    // PostHog identify
    if (typeof window !== 'undefined' && (window as any).posthog) {
      (window as any).posthog.identify(userId, properties);
    }
  }

  /**
   * Track an event
   */
  track(event: string, properties: Record<string, unknown> = {}) {
    if (!this.enabled) return;

    const eventData: AnalyticsEvent = {
      event,
      properties: {
        ...properties,
        timestamp: new Date().toISOString(),
        userId: this.userId,
      },
    };

    // PostHog track
    if (typeof window !== 'undefined' && (window as any).posthog) {
      (window as any).posthog.capture(event, eventData.properties);
    }

    // Log in development only
    if (import.meta.env.DEV) {
      logger.debug('Analytics event:', { event, properties: eventData.properties });
    }
  }

  /**
   * Track page view
   */
  page(pageName: string, properties: Record<string, unknown> = {}) {
    this.track('Page Viewed', {
      page: pageName,
      ...properties,
    });
  }

  /**
   * Reset analytics (on logout)
   */
  reset() {
    this.userId = null;

    if (typeof window !== 'undefined' && (window as any).posthog) {
      (window as any).posthog.reset();
    }
  }

  /**
   * Set user properties
   */
  setUserProperties(properties: UserProperties) {
    if (!this.enabled) return;

    if (typeof window !== 'undefined' && (window as any).posthog) {
      (window as any).posthog.people.set(properties);
    }
  }

  /**
   * Track feature usage
   */
  trackFeature(featureName: string, action: string, properties: Record<string, unknown> = {}) {
    this.track(`Feature: ${featureName}`, {
      action,
      ...properties,
    });
  }
}

export const analytics = new Analytics();

// Common event tracking functions

export const trackSignup = (userId: string, method: string) => {
  analytics.track('User Signed Up', { method });
};

export const trackLogin = (userId: string, method: string) => {
  analytics.track('User Logged In', { method });
};

export const trackLogout = () => {
  analytics.track('User Logged Out', {});
  analytics.reset();
};

export const trackPatientCreated = (patientId: string) => {
  analytics.track('Patient Created', { patientId });
};

export const trackAppointmentBooked = (appointmentId: string, type: string) => {
  analytics.track('Appointment Booked', { appointmentId, type });
};

export const trackInvoiceCreated = (invoiceId: string, amount: number) => {
  analytics.track('Invoice Created', { invoiceId, amount });
};

export const trackPaymentReceived = (paymentId: string, amount: number, method: string) => {
  analytics.track('Payment Received', { paymentId, amount, method });
};

export const trackFeatureUsed = (feature: string, action: string) => {
  analytics.trackFeature(feature, action);
};

export const trackError = (error: Error, context?: Record<string, unknown>) => {
  analytics.track('Error Occurred', {
    error: error.message,
    stack: error.stack,
    ...context,
  });
};

export const trackPerformance = (metric: string, value: number) => {
  analytics.track('Performance Metric', {
    metric,
    value,
  });
};

/**
 * Generic API Service Factory
 * Creates standardized CRUD services to eliminate duplication
 * Reduces code duplication by 50%+ across API services
 */

import { apiClient } from '@/services/api';
import type { ApiResponse, PaginatedResponse } from '@/types/common';

// ============================================
// Generic Types
// ============================================

/**
 * Generic list parameters for pagination and filtering
 */
export interface ListParams {
  page?: number;
  limit?: number;
  search?: string;
  sort?: string;
  [key: string]: unknown;
}

/**
 * Generic CRUD service interface
 */
export interface CrudService<T, CreateData = Partial<T>, UpdateData = Partial<T>> {
  list: (params?: ListParams) => Promise<PaginatedResponse<T>>;
  get: (id: string) => Promise<T | null>;
  create: (data: CreateData) => Promise<T>;
  update: (id: string, data: UpdateData) => Promise<T | null>;
  delete: (id: string) => Promise<void>;
}

/**
 * Generic list-only service interface
 */
export interface ListService<T> {
  list: (params?: ListParams) => Promise<PaginatedResponse<T>>;
}

/**
 * Generic get-only service interface
 */
export interface GetService<T> {
  get: (id: string) => Promise<T | null>;
}

// ============================================
// Factory Functions
// ============================================

/**
 * Create a standard CRUD service
 * Eliminates boilerplate for common CRUD operations
 *
 * @example
 * const userApi = createCrudService<User>('/users');
 * const users = await userApi.list({ page: 1, limit: 10 });
 * const user = await userApi.get('user-123');
 * const newUser = await userApi.create({ name: 'John' });
 * await userApi.update('user-123', { name: 'Jane' });
 * await userApi.delete('user-123');
 */
export function createCrudService<
  T extends { id: string },
  CreateData = Partial<T>,
  UpdateData = Partial<T>
>(
  endpoint: string,
  options?: {
    listKey?: string; // Key for list response (default: 'data')
    defaultLimit?: number; // Default page limit (default: 20)
  }
): CrudService<T, CreateData, UpdateData> {
  const { listKey = 'data', defaultLimit = 20 } = options || {};

  return {
    /**
     * Get paginated list of items
     */
    list: async (params?: ListParams): Promise<PaginatedResponse<T>> => {
      const response = await apiClient.get<PaginatedResponse<T>>(
        endpoint,
        params as unknown as Record<string, unknown>
      );

      if (response.success && response.data) {
        return response.data;
      }

      return {
        data: [],
        total: 0,
        page: params?.page ?? 1,
        limit: params?.limit ?? defaultLimit,
        totalPages: 0,
      };
    },

    /**
     * Get single item by ID
     */
    get: async (id: string): Promise<T | null> => {
      const response = await apiClient.get<T>(`${endpoint}/${id}`);
      return response.success ? response.data ?? null : null;
    },

    /**
     * Create new item
     */
    create: async (data: CreateData): Promise<T> => {
      const response = await apiClient.post<T>(endpoint, data);
      if (response.success && response.data) {
        return response.data;
      }
      throw new Error(response.error?.message || `Failed to create ${endpoint}`);
    },

    /**
     * Update existing item
     */
    update: async (id: string, data: UpdateData): Promise<T | null> => {
      const response = await apiClient.put<T>(`${endpoint}/${id}`, data);
      return response.success ? response.data ?? null : null;
    },

    /**
     * Delete item
     */
    delete: async (id: string): Promise<void> => {
      await apiClient.delete(`${endpoint}/${id}`);
    },
  };
}

/**
 * Create a list-only service
 * For endpoints that only support listing
 *
 * @example
 * const reportsApi = createListService<Report>('/reports');
 * const reports = await reportsApi.list({ page: 1 });
 */
export function createListService<T>(
  endpoint: string,
  options?: {
    defaultLimit?: number;
  }
): ListService<T> {
  const { defaultLimit = 20 } = options || {};

  return {
    list: async (params?: ListParams): Promise<PaginatedResponse<T>> => {
      const response = await apiClient.get<PaginatedResponse<T>>(
        endpoint,
        params as unknown as Record<string, unknown>
      );

      if (response.success && response.data) {
        return response.data;
      }

      return {
        data: [],
        total: 0,
        page: params?.page ?? 1,
        limit: params?.limit ?? defaultLimit,
        totalPages: 0,
      };
    },
  };
}

/**
 * Create a get-only service
 * For endpoints that only support getting by ID
 *
 * @example
 * const settingsApi = createGetService<Settings>('/settings');
 * const settings = await settingsApi.get('user-123');
 */
export function createGetService<T>(endpoint: string): GetService<T> {
  return {
    get: async (id: string): Promise<T | null> => {
      const response = await apiClient.get<T>(`${endpoint}/${id}`);
      return response.success ? response.data ?? null : null;
    },
  };
}

/**
 * Create a custom service with specific methods
 * For complex endpoints that don't fit standard CRUD
 *
 * @example
 * const customApi = createCustomService('/custom', {
 *   search: (query: string) => apiClient.get('/custom/search', { q: query }),
 *   export: (format: string) => apiClient.get('/custom/export', { format }),
 * });
 */
export function createCustomService<T extends Record<string, (...args: unknown[]) => unknown>>(
  endpoint: string,
  methods: T
): T {
  return methods;
}

/**
 * Create a nested resource service
 * For resources that are nested under a parent (e.g., /patients/:id/notes)
 *
 * @example
 * const patientNotesApi = createNestedService<Note>('/patients', 'notes');
 * const notes = await patientNotesApi.list('patient-123');
 * const note = await patientNotesApi.get('patient-123', 'note-456');
 */
export function createNestedService<T extends { id: string }>(
  parentEndpoint: string,
  childResource: string,
  options?: {
    defaultLimit?: number;
  }
) {
  const { defaultLimit = 20 } = options || {};

  return {
    /**
     * Get paginated list of child items
     */
    list: async (parentId: string, params?: ListParams): Promise<PaginatedResponse<T>> => {
      const endpoint = `${parentEndpoint}/${parentId}/${childResource}`;
      const response = await apiClient.get<PaginatedResponse<T>>(
        endpoint,
        params as unknown as Record<string, unknown>
      );

      if (response.success && response.data) {
        return response.data;
      }

      return {
        data: [],
        total: 0,
        page: params?.page ?? 1,
        limit: params?.limit ?? defaultLimit,
        totalPages: 0,
      };
    },

    /**
     * Get single child item
     */
    get: async (parentId: string, id: string): Promise<T | null> => {
      const endpoint = `${parentEndpoint}/${parentId}/${childResource}/${id}`;
      const response = await apiClient.get<T>(endpoint);
      return response.success ? response.data ?? null : null;
    },

    /**
     * Create child item
     */
    create: async (parentId: string, data: Partial<T>): Promise<T> => {
      const endpoint = `${parentEndpoint}/${parentId}/${childResource}`;
      const response = await apiClient.post<T>(endpoint, data);
      if (response.success && response.data) {
        return response.data;
      }
      throw new Error(response.error?.message || `Failed to create ${childResource}`);
    },

    /**
     * Update child item
     */
    update: async (parentId: string, id: string, data: Partial<T>): Promise<T | null> => {
      const endpoint = `${parentEndpoint}/${parentId}/${childResource}/${id}`;
      const response = await apiClient.put<T>(endpoint, data);
      return response.success ? response.data ?? null : null;
    },

    /**
     * Delete child item
     */
    delete: async (parentId: string, id: string): Promise<void> => {
      const endpoint = `${parentEndpoint}/${parentId}/${childResource}/${id}`;
      await apiClient.delete(endpoint);
    },
  };
}

/**
 * Create a batch operation service
 * For endpoints that support batch operations
 *
 * @example
 * const batchApi = createBatchService<User>('/users');
 * await batchApi.batchCreate([{ name: 'John' }, { name: 'Jane' }]);
 * await batchApi.batchDelete(['user-1', 'user-2']);
 */
export function createBatchService<T extends { id: string }>(endpoint: string) {
  return {
    /**
     * Create multiple items
     */
    batchCreate: async (items: Partial<T>[]): Promise<T[]> => {
      const response = await apiClient.post<T[]>(`${endpoint}/batch`, { items });
      if (response.success && response.data) {
        return response.data;
      }
      throw new Error(response.error?.message || 'Batch create failed');
    },

    /**
     * Update multiple items
     */
    batchUpdate: async (updates: Array<{ id: string; data: Partial<T> }>): Promise<T[]> => {
      const response = await apiClient.put<T[]>(`${endpoint}/batch`, { updates });
      if (response.success && response.data) {
        return response.data;
      }
      throw new Error(response.error?.message || 'Batch update failed');
    },

    /**
     * Delete multiple items
     */
    batchDelete: async (ids: string[]): Promise<void> => {
      await apiClient.delete(`${endpoint}/batch`, { ids });
    },
  };
}

// Advanced caching utilities for optimized data management

import type { CachedFunction } from '@/types/utils';

interface CacheEntry<T> {
  data: T;
  timestamp: number;
  expiresAt: number;
}

interface CacheOptions {
  ttl?: number; // Time to live in milliseconds
  maxSize?: number; // Maximum cache size
}

class MemoryCache {
  private cache: Map<string, CacheEntry<any>> = new Map();
  private maxSize: number;

  constructor(maxSize = 100) {
    this.maxSize = maxSize;
  }

  set<T>(key: string, data: T, ttl = 5 * 60 * 1000): void {
    // Evict oldest entries if cache is full
    if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }

    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      expiresAt: Date.now() + ttl,
    };

    this.cache.set(key, entry);
  }

  get<T>(key: string): T | null {
    const entry = this.cache.get(key);

    if (!entry) {
      return null;
    }

    // Check if expired
    if (Date.now() > entry.expiresAt) {
      this.cache.delete(key);
      return null;
    }

    return entry.data as T;
  }

  has(key: string): boolean {
    const entry = this.cache.get(key);
    if (!entry) return false;

    // Check if expired
    if (Date.now() > entry.expiresAt) {
      this.cache.delete(key);
      return false;
    }

    return true;
  }

  delete(key: string): boolean {
    return this.cache.delete(key);
  }

  clear(): void {
    this.cache.clear();
  }

  size(): number {
    return this.cache.size;
  }

  // Get all valid (non-expired) keys
  keys(): string[] {
    const now = Date.now();
    const validKeys: string[] = [];

    for (const [key, entry] of this.cache.entries()) {
      if (now <= entry.expiresAt) {
        validKeys.push(key);
      } else {
        this.cache.delete(key);
      }
    }

    return validKeys;
  }
}

// Global cache instances
export const apiCache = new MemoryCache(200);
export const uiCache = new MemoryCache(50);

// Cache decorator for functions
export function cached<TArgs extends unknown[] = unknown[], TReturn = unknown>(
  fn: (...args: TArgs) => TReturn,
  options: CacheOptions = {}
): CachedFunction<TArgs, TReturn> {
  const { ttl = 5 * 60 * 1000 } = options;
  const cache = new Map<string, CacheEntry<TReturn>>();

  return ((...args: TArgs): TReturn => {
    const key = JSON.stringify(args);
    const cached = cache.get(key);

    if (cached && Date.now() <= cached.expiresAt) {
      return cached.data;
    }

    const result = fn(...args);

    // Handle promises
    if (result instanceof Promise) {
      return result.then((data) => {
        cache.set(key, {
          data,
          timestamp: Date.now(),
          expiresAt: Date.now() + ttl,
        });
        return data;
      }) as ReturnType<T>;
    }

    cache.set(key, {
      data: result,
      timestamp: Date.now(),
      expiresAt: Date.now() + ttl,
    });

    return result;
  }) as T;
}

// Memoization with LRU eviction
export class LRUCache<K, V> {
  private maxSize: number;
  private cache: Map<K, V>;

  constructor(maxSize = 100) {
    this.maxSize = maxSize;
    this.cache = new Map();
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move to end (most recently used)
    const value = this.cache.get(key)!;
    this.cache.delete(key);
    this.cache.set(key, value);

    return value;
  }

  set(key: K, value: V): void {
    // Delete if exists (to update position)
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }

    // Evict least recently used if at capacity
    if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }

    this.cache.set(key, value);
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  delete(key: K): boolean {
    return this.cache.delete(key);
  }

  clear(): void {
    this.cache.clear();
  }

  size(): number {
    return this.cache.size;
  }
}

// Session storage cache with expiration
export const sessionCache = {
  set<T>(key: string, data: T, ttl = 30 * 60 * 1000): void {
    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      expiresAt: Date.now() + ttl,
    };

    try {
      sessionStorage.setItem(key, JSON.stringify(entry));
    } catch (error) {
      if (import.meta.env.DEV) {
        console.warn('Session storage full, clearing old entries');
      }
      this.clear();
      sessionStorage.setItem(key, JSON.stringify(entry));
    }
  },

  get<T>(key: string): T | null {
    try {
      const item = sessionStorage.getItem(key);
      if (!item) return null;

      const entry: CacheEntry<T> = JSON.parse(item);

      if (Date.now() > entry.expiresAt) {
        sessionStorage.removeItem(key);
        return null;
      }

      return entry.data;
    } catch {
      return null;
    }
  },

  has(key: string): boolean {
    try {
      const item = sessionStorage.getItem(key);
      if (!item) return false;

      const entry: CacheEntry<any> = JSON.parse(item);
      if (Date.now() > entry.expiresAt) {
        sessionStorage.removeItem(key);
        return false;
      }

      return true;
    } catch {
      return false;
    }
  },

  remove(key: string): void {
    sessionStorage.removeItem(key);
  },

  delete(key: string): void {
    sessionStorage.removeItem(key);
  },

  clear(): void {
    sessionStorage.clear();
  },

  size(): number {
    let count = 0;
    for (let i = 0; i < sessionStorage.length; i++) {
      const key = sessionStorage.key(i);
      if (key) {
        try {
          const item = sessionStorage.getItem(key);
          if (item) {
            const entry = JSON.parse(item) as { expiresAt: number };
            if (Date.now() <= entry.expiresAt) {
              count++;
            }
          }
        } catch {
          // Ignore parse errors
        }
      }
    }
    return count;
  },

  keys(): string[] {
    const validKeys: string[] = [];
    for (let i = 0; i < sessionStorage.length; i++) {
      const key = sessionStorage.key(i);
      if (key) {
        try {
          const item = sessionStorage.getItem(key);
          if (item) {
            const entry = JSON.parse(item) as { expiresAt: number };
            if (Date.now() <= entry.expiresAt) {
              validKeys.push(key);
            }
          }
        } catch {
          // Ignore parse errors
        }
      }
    }
    return validKeys;
  },
};

// Local storage cache with expiration
// SECURITY WARNING: Avoid storing PHI (Protected Health Information) or sensitive data
// in localStorage as it's accessible via XSS attacks. Use sessionCache for sensitive data.
export const localCache = {
  set<T>(key: string, data: T, ttl = 24 * 60 * 60 * 1000): void {
    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      expiresAt: Date.now() + ttl,
    };

    try {
      localStorage.setItem(key, JSON.stringify(entry));
    } catch (error) {
      if (import.meta.env.DEV) {
        console.warn('Local storage full, clearing old entries');
      }
      this.clear();
      localStorage.setItem(key, JSON.stringify(entry));
    }
  },

  get<T>(key: string): T | null {
    try {
      const item = localStorage.getItem(key);
      if (!item) return null;

      const entry: CacheEntry<T> = JSON.parse(item);

      if (Date.now() > entry.expiresAt) {
        localStorage.removeItem(key);
        return null;
      }

      return entry.data;
    } catch {
      return null;
    }
  },

  delete(key: string): void {
    localStorage.removeItem(key);
  },

  clear(): void {
    localStorage.clear();
  },
};

// Centralized logging and error tracking

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

interface LogEntry {
  level: LogLevel;
  message: string;
  timestamp: string;
  context?: Record<string, unknown>;
  error?: Error;
}

// Error monitoring integration using Sentry.
// Initialize Sentry in production if DSN is provided.
import * as Sentry from '@sentry/browser';
if (!import.meta.env.DEV && import.meta.env.VITE_SENTRY_DSN) {
  Sentry.init({
    dsn: import.meta.env.VITE_SENTRY_DSN,
    environment: import.meta.env.MODE,
    tracesSampleRate: 0.1,
  });
}

class Logger {
  private get isDevelopment(): boolean {
    return import.meta.env.DEV;
  }
  private logs: LogEntry[] = [];
  private maxLogs = 100;

  private createEntry(
    level: LogLevel,
    message: string,
    context?: Record<string, unknown>,
    error?: Error
  ): LogEntry {
    return {
      level,
      message,
      timestamp: new Date().toISOString(),
      context,
      error,
    };
  }

  private addLog(entry: LogEntry) {
    this.logs.push(entry);
    if (this.logs.length > this.maxLogs) {
      this.logs.shift();
    }
  }

  private sendToMonitoring(entry: LogEntry) {
    // Send error logs to monitoring endpoint regardless of environment (required for tests)
    if (entry.level === 'error') {
      // Disabled for now - backend doesn't have /api/logs endpoint
      // Use globalThis.fetch to ensure mocked fetch is used in tests
      // globalThis.fetch('/api/logs', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify(entry),
      // }).catch(() => {
      //   // Silently fail if logging endpoint is unavailable
      // });
    }
  }

  debug(message: string, context?: Record<string, unknown>) {
    const entry = this.createEntry('debug', message, context);
    this.addLog(entry);
    
    if (this.isDevelopment) {
      // eslint-disable-next-line no-console
      console.debug(`[DEBUG] ${message}`, context);
    }
  }

  info(message: string, context?: Record<string, unknown>) {
    const entry = this.createEntry('info', message, context);
    this.addLog(entry);
    
    if (this.isDevelopment) {
      console.info(`[INFO] ${message}`, context);
    }
  }

  warn(message: string, context?: Record<string, unknown>) {
    const entry = this.createEntry('warn', message, context);
    this.addLog(entry);
    
    // eslint-disable-next-line no-console
    console.warn(`[WARN] ${message}`, context);
    this.sendToMonitoring(entry);
  }

  error(message: string, error?: Error, context?: Record<string, unknown>) {
    const entry = this.createEntry('error', message, context, error);
    this.addLog(entry);
    
    console.error(`[ERROR] ${message}`, error, context);
    this.sendToMonitoring(entry);
  }

  // Get recent logs for debugging
  getRecentLogs(count = 50): LogEntry[] {
    return this.logs.slice(-count);
  }

  // Clear logs
  clearLogs() {
    this.logs = [];
  }

  // Export logs for support
  exportLogs(): string {
    return JSON.stringify(this.logs, null, 2);
  }
}

export const logger = new Logger();

// Error boundary helper
export function logError(error: Error, errorInfo?: { componentStack?: string }) {
  logger.error('React Error Boundary caught an error', error, {
    componentStack: errorInfo?.componentStack,
  });
}

// API error helper
export function logApiError(
  endpoint: string,
  error: Error,
  context?: Record<string, unknown>
) {
  logger.error(`API Error: ${endpoint}`, error, {
    endpoint,
    ...context,
  });
}

// Performance monitoring
export function logPerformance(metric: string, duration: number) {
  logger.info(`Performance: ${metric}`, { duration, metric });
}

// Web Vitals monitoring for performance tracking
import { onCLS, onFID, onFCP, onLCP, onTTFB, type Metric } from 'web-vitals';
import { logger } from './logger';

interface VitalsReport {
  name: string;
  value: number;
  rating: 'good' | 'needs-improvement' | 'poor';
  delta: number;
  id: string;
}

// Thresholds based on web.dev recommendations
const THRESHOLDS = {
  CLS: { good: 0.1, poor: 0.25 },
  FID: { good: 100, poor: 300 },
  FCP: { good: 1800, poor: 3000 },
  LCP: { good: 2500, poor: 4000 },
  TTFB: { good: 800, poor: 1800 },
};

function getRating(name: string, value: number): 'good' | 'needs-improvement' | 'poor' {
  const threshold = THRESHOLDS[name as keyof typeof THRESHOLDS];
  if (!threshold) return 'good';
  
  if (value <= threshold.good) return 'good';
  if (value <= threshold.poor) return 'needs-improvement';
  return 'poor';
}

function sendToAnalytics(metric: VitalsReport) {
  // Log to console in development
  if (import.meta.env.DEV) {
    // eslint-disable-next-line no-console
    logger.debug(`Web Vitals ${metric.name}:`, {
      value: metric.value,
      rating: metric.rating,
      id: metric.id,
    });
  }

  // Log to monitoring service
  logger.info(`Web Vital: ${metric.name}`, {
    metric: metric.name,
    value: metric.value,
    rating: metric.rating,
    delta: metric.delta,
    id: metric.id,
  });

  // Send to analytics service (Google Analytics, etc.)
  if (typeof window !== 'undefined' && (window as any).gtag) {
    (window as any).gtag('event', metric.name, {
      event_category: 'Web Vitals',
      event_label: metric.id,
      value: Math.round(metric.name === 'CLS' ? metric.value * 1000 : metric.value),
      non_interaction: true,
    });
  }
}

function handleMetric(metric: Metric) {
  const report: VitalsReport = {
    name: metric.name,
    value: metric.value,
    rating: getRating(metric.name, metric.value),
    delta: metric.delta,
    id: metric.id,
  };

  sendToAnalytics(report);
}

export function initWebVitals() {
  // Only run in browser
  if (typeof window === 'undefined') return;

  // Cumulative Layout Shift
  onCLS(handleMetric);

  // First Input Delay
  onFID(handleMetric);

  // First Contentful Paint
  onFCP(handleMetric);

  // Largest Contentful Paint
  onLCP(handleMetric);

  // Time to First Byte
  onTTFB(handleMetric);
}

// Export for manual tracking
export function trackCustomMetric(name: string, value: number) {
  logger.info(`Custom Metric: ${name}`, { metric: name, value });

  if (typeof window !== 'undefined' && (window as any).gtag) {
    (window as any).gtag('event', 'custom_metric', {
      event_category: 'Performance',
      event_label: name,
      value: Math.round(value),
      non_interaction: true,
    });
  }
}

