                        {plan.status}
                      </Badge>
                    </div>
                    <Separator />
                    <div className="grid grid-cols-3 gap-4 text-center">
                      <div>
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Total Cost</p>
