                  documents.map((doc) => (
                    <div key={doc.id} className={`flex items-center justify-between p-5 rounded-2xl border border-slate-100 transition-colors ${doc.is_completed ? 'bg-slate-50/50' : 'hover:bg-blue-50/30 group'}`}>
