                            setSelectedType(type);
                            handleNext();
                          }}
                          className={cn(
                            "group p-6 rounded-2xl text-left border-2 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02]",
                            selectedType?.id === type.id 
                              ? "bg-blue-600 border-blue-600 text-white shadow-xl shadow-blue-200" 
                              : "bg-white border-slate-100 hover:border-blue-200 text-slate-800"
                          )}
                        >
                          <div className="flex justify-between items-start mb-4">
                            <span className="text-4xl">{type.icon}</span>
                            <Badge variant="outline" className={cn(
                              "font-bold uppercase tracking-widest",
                              selectedType?.id === type.id ? "border-blue-400 text-white" : "border-slate-200 text-slate-400"
                            )}>
                              {type.duration}
                            </Badge>
                          </div>
                          <h3 className="text-xl font-extrabold mb-1">{type.name}</h3>
                          <p className={cn(
                            "text-sm leading-relaxed",
                            selectedType?.id === type.id ? "text-blue-50" : "text-slate-500"
                          )}>
                            {type.description}
                          </p>
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Step 2: Date & Time */}
                {currentStep === 1 && (
                  <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="space-y-2">
                      <h2 className="text-2xl font-black text-slate-800 tracking-tight">Pick a convenient time</h2>
                      <p className="text-slate-500">We recommended booking at least 48 hours in advance.</p>
                    </div>

                    <div className="flex flex-col lg:flex-row gap-10">
                      {/* Calendar Sidebar */}
                      <div className="flex-1 space-y-6">
                        <Label className="text-sm font-bold uppercase tracking-wider text-slate-400 pl-1">Available Dates</Label>
                        <div className="grid grid-cols-7 gap-2">
                          {[...Array(14)].map((_, i) => {
                            const date = addDays(startOfToday(), i);
                            const isSelected = isSameDay(date, selectedDate);
                            return (
                              <button
                                key={i}
                                onClick={() => setSelectedDate(date)}
                                className={cn(
                                  "flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all duration-300",
                                  isSelected 
                                    ? "bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-100 scale-105" 
                                    : "bg-slate-50 border-transparent hover:border-blue-200"
                                )}
                              >
                                <span className={cn("text-[10px] font-black uppercase mb-1", isSelected ? "text-blue-100" : "text-slate-400")}>
                                  {format(date, 'eee')}
                                </span>
                                <span className="text-lg font-black tracking-tighter">
                                  {format(date, 'd')}
                                </span>
                              </button>
                            );
                          })}
                        </div>
                      </div>

                      {/* Time Slots */}
                      <div className="lg:w-[300px] space-y-6">
                        <Label className="text-sm font-bold uppercase tracking-wider text-slate-400 pl-1">Preferred Time</Label>
                        <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                          {availability.map((slot, idx) => (
                            <button
                              key={idx}
                              disabled={!slot.is_available}
                              onClick={() => {
                                setSelectedSlot(slot.start_time);
                              }}
                              className={cn(
                                "w-full p-4 rounded-2xl flex justify-between items-center transition-all duration-300 border-2",
                                selectedSlot === slot.start_time 
                                  ? "bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-100" 
                                  : slot.is_available 
                                    ? "bg-white border-slate-100 hover:border-emerald-200" 
                                    : "bg-slate-50 border-slate-50 opacity-40 cursor-not-allowed"
                              )}
                            >
                              <div className="flex items-center gap-3">
                                <Clock className={cn("w-4 h-4", selectedSlot === slot.start_time ? "text-emerald-100" : "text-slate-400")} />
                                <span className="text-lg font-black tracking-tight">{slot.start_time}</span>
                              </div>
                              {selectedSlot === slot.start_time && <CheckCircle2 className="w-5 h-5 text-white" />}
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                {/* Step 3: Info */}
                {currentStep === 2 && (
                  <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="space-y-2">
                      <h2 className="text-2xl font-black text-slate-800 tracking-tight">Tell us about yourself</h2>
                      <p className="text-slate-500">Please provide your contact information to finish the booking.</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-6">
                        <div className="space-y-3">
                          <Label htmlFor="firstName" className="text-sm font-bold tracking-tight">First Name</Label>
                          <div className="relative group">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                            <Input 
                              id="firstName"
                              placeholder="e.g. John" 
                              className="pl-11 h-14 rounded-2xl border-slate-200 focus:ring-4 focus:ring-blue-100 transition-all font-medium"
                              value={formData.firstName}
                              onChange={(e) => setFormData({...formData, firstName: e.target.value})}
                            />
                          </div>
                        </div>
                        <div className="space-y-3">
                          <Label htmlFor="lastName" className="text-sm font-bold tracking-tight">Last Name</Label>
                          <div className="relative group">
                             <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                            <Input 
                              id="lastName"
                              placeholder="e.g. Doe" 
                              className="pl-11 h-14 rounded-2xl border-slate-200 focus:ring-4 focus:ring-blue-100 transition-all font-medium"
                              value={formData.lastName}
                              onChange={(e) => setFormData({...formData, lastName: e.target.value})}
                            />
                          </div>
                        </div>
                      </div>

                      <div className="space-y-6">
                        <div className="space-y-3">
                          <Label htmlFor="email" className="text-sm font-bold tracking-tight">Email Address</Label>
                          <div className="relative group">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                            <Input 
                              id="email"
                              type="email" 
                              placeholder="john@example.com" 
                              className="pl-11 h-14 rounded-2xl border-slate-200 focus:ring-4 focus:ring-blue-100 transition-all font-medium"
                              value={formData.email}
                              onChange={(e) => setFormData({...formData, email: e.target.value})}
                            />
                          </div>
                        </div>
                        <div className="space-y-3">
                          <Label htmlFor="phone" className="text-sm font-bold tracking-tight">Phone Number</Label>
                          <div className="relative group">
                            <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                            <Input 
                              id="phone"
                              type="tel" 
                              placeholder="(555) 000-0000" 
                              className="pl-11 h-14 rounded-2xl border-slate-200 focus:ring-4 focus:ring-blue-100 transition-all font-medium"
                              value={formData.phone}
                              onChange={(e) => setFormData({...formData, phone: e.target.value})}
                            />
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="space-y-3">
                      <Label htmlFor="reason" className="text-sm font-bold tracking-tight">Reason for visit (Optional)</Label>
                      <Textarea 
                        id="reason"
                        placeholder="Describe any symptoms or specific concerns..." 
                        className="min-h-[120px] rounded-2xl border-slate-200 focus:ring-4 focus:ring-blue-100 transition-all font-medium p-6"
                        value={formData.reason}
                        onChange={(e) => setFormData({...formData, reason: e.target.value})}
                      />
                    </div>
                  </div>
                )}

                {/* Step 4: Review */}
                {currentStep === 3 && (
                  <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="text-center space-y-2">
                       <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-emerald-100 text-emerald-600 mb-4 shadow-inner ring-4 ring-emerald-50">
                        <CheckCircle2 className="w-10 h-10" />
                      </div>
                      <h2 className="text-3xl font-black text-slate-800 tracking-tight">Almost there!</h2>
                      <p className="text-slate-500 text-lg">Please check the details of your appointment below.</p>
                    </div>

                    <div className="bg-slate-50 rounded-3xl p-8 border-2 border-slate-100 shadow-inner grid grid-cols-1 md:grid-cols-2 gap-10">
                      <div className="space-y-6">
                        <div className="flex flex-col gap-1">
                          <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Patient Name</span>
                          <p className="text-xl font-bold flex items-center gap-2">
                            {formData.firstName} {formData.lastName}
                            <Badge variant="secondary" className="bg-blue-50 text-blue-600 border-none font-bold">New Patient</Badge>
                          </p>
                        </div>
                        <div className="flex flex-col gap-1">
                          <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Contact Information</span>
                          <div className="space-y-1">
                            <p className="text-lg font-bold flex items-center gap-2 text-slate-600">
                              <Mail className="w-4 h-4" /> {formData.email}
                            </p>
                            <p className="text-lg font-bold flex items-center gap-2 text-slate-600">
                              <Phone className="w-4 h-4" /> {formData.phone}
                            </p>
                          </div>
                        </div>
                      </div>

                      <div className="space-y-6">
                        <div className="flex flex-col gap-1">
                          <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Appointment Type</span>
                          <p className="text-xl font-bold text-blue-600">{selectedType?.name}</p>
                        </div>
                        <div className="flex flex-col gap-1">
                          <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Date & Time</span>
                          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mt-2">
                            <p className="text-lg font-black text-slate-800 flex items-center gap-2">
                              <Calendar className="w-5 h-5 text-blue-500" />
                              {format(selectedDate, 'EEEE, MMMM d, yyyy')}
                            </p>
                            <p className="text-2xl font-black text-emerald-600 flex items-center gap-2 mt-1">
                              <Clock className="w-6 h-6 text-emerald-500" />
                              {selectedSlot}
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="bg-amber-50 rounded-2xl p-6 border border-amber-200/50 flex gap-4">
                      <AlertCircle className="w-6 h-6 text-amber-500 shrink-0 mt-1" />
                      <p className="text-sm text-amber-800 leading-relaxed font-medium">
                        <strong>Important:</strong> Your booking is a "Request" until confirmed by our staff. 
                        You will receive an email confirmation once we review your appointment.
                      </p>
                    </div>
                  </div>
                )}

              </CardContent>

              {/* Action Bar */}
              <div className="bg-slate-50/50 border-t border-slate-100 p-6 flex items-center justify-between gap-4">
                <Button 
                  variant="ghost" 
                  onClick={handleBack}
                  disabled={currentStep === 0}
                  className="px-8 h-12 rounded-xl border-none font-bold text-slate-500 hover:text-slate-900 transition-all hover:bg-slate-100"
                >
                  <ChevronLeft className="w-5 h-5 mr-1" /> Back
                </Button>
                
                {currentStep === STEPS.length - 1 ? (
                  <Button 
                    onClick={() => {
                      toast({
                        title: "Booking Submitted!",
                        description: "Your request has been sent to the clinic.",
                      });
                      navigate('/book/success');
                    }}
                    className="px-12 h-14 rounded-2xl font-black text-lg bg-emerald-600 hover:bg-emerald-700 shadow-xl shadow-emerald-100 transition-all hover:scale-[1.05] active:scale-95 text-white"
                  >
                    Confirm Booking <ArrowRight className="ml-2 w-5 h-5" />
                  </Button>
                ) : (
                  <Button 
                    disabled={!isStepComplete()}
                    onClick={handleNext}
                    className="px-12 h-14 rounded-2xl font-black text-lg bg-blue-600 hover:bg-blue-700 shadow-xl shadow-blue-100 transition-all hover:scale-[1.05] active:scale-95 text-white"
                  >
                    Continue <ChevronRight className="ml-2 w-5 h-5" />
                  </Button>
                )}
              </div>
            </Card>
          </motion.div>
        </AnimatePresence>

        {/* Footer Info */}
        <div className="mt-12 text-center text-slate-400 space-y-4">
          <div className="flex items-center justify-center gap-6">
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4" />
              <span className="text-xs font-bold uppercase tracking-widest">123 Dental Lane, New York, NY</span>
            </div>
            <div className="flex items-center gap-2">
              <Phone className="w-4 h-4" />
              <span className="text-xs font-bold uppercase tracking-widest">(555) 123-4567</span>
            </div>
          </div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">Powered by CoreDent Prime • Enterprise Clinical Systems</p>
        </div>
      </main>

      <style dangerouslySetInnerHTML={{ __html: `
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }
      `}} />
    </div>
  );
}

// ============================================
// CoreDent PMS - Reports Page
// Analytics dashboard for clinic owners
// ============================================

import { useState, useEffect, useMemo } from 'react';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Calendar } from '@/components/ui/calendar';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { 
  Download, 
  Calendar as CalendarIcon,
  Users,
  DollarSign,
  TrendingUp,
  Clock,
  AlertTriangle,
  CheckCircle2,
  XCircle
} from 'lucide-react';

// Components & Hooks
import { MetricCard } from '@/components/reports/MetricCard';
import { reportsApi } from '@/services/reportsApi';
import { useApiRequest } from '@/hooks/useApiRequest';
import { useDateRange } from '@/hooks/useDateRange';
import { cn } from '@/lib/utils';
import type { ReportType } from '@/types/reports';

// Extracted Charts
import { RevenueChart } from '@/components/reports/charts/RevenueChart';
import { AppointmentPieChart } from '@/components/reports/charts/AppointmentPieChart';
import { DailyAppointmentsChart } from '@/components/reports/charts/DailyAppointmentsChart';
import { MonthlyRevenueChart } from '@/components/reports/charts/MonthlyRevenueChart';
import { UtilizationCharts } from '@/components/reports/charts/UtilizationCharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

const COLORS = [
  'hsl(var(--chart-1))',
  'hsl(var(--chart-2))',
  'hsl(var(--chart-3))',
  'hsl(var(--chart-4))',
  'hsl(var(--chart-5))',
  'hsl(var(--muted-foreground))',
];

export default function Reports() {
  const { 
    dateRange, 
    selectedPreset, 
    handlePresetChange, 
    setCustomRange, 
    PRESET_RANGES 
  } = useDateRange('last30days');

  // Memoize options to prevent execute function from being recreated
  // No error message - we'll handle empty state gracefully
  const apiOptions = useMemo(() => ({}), []);

  const {
    data: metrics,
    isLoading,
    error,
    execute: loadMetrics
  } = useApiRequest(reportsApi.getDashboardMetrics, apiOptions);

  const [activeTab, setActiveTab] = useState('overview');

  // effect:audited — Load metrics when date range changes
  useEffect(() => {
    logger.debug('Loading metrics for date range', { dateRange });
    loadMetrics(dateRange);
  }, [dateRange, loadMetrics]);

  // Log when data changes
  useEffect(() => {
    logger.debug('Data updated', { 
      hasMetrics: !!metrics, 
      isLoading, 
      error,
      metricsPreview: metrics ? {
        appointmentsTotal: metrics.appointments?.total,
        revenueTotal: metrics.revenue?.totalRevenue
      } : null
    });
  }, [metrics, isLoading, error]);

  const handleExport = (reportType: ReportType) => {
    if (!metrics) return;
    const csv = reportsApi.exportToCSV(reportType, metrics, dateRange);
    const filename = `${reportType}-report-${format(dateRange.from, 'yyyy-MM-dd')}`;
    reportsApi.downloadCSV(filename, csv);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(amount);
  };

  // Check if we have valid empty data (no error, but all zeros)
  const hasNoData = metrics && 
    metrics.appointments && 
    metrics.revenue && 
    metrics.appointments.total === 0 && 
    metrics.revenue.totalRevenue === 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold">Reports</h1>
          <p className="text-muted-foreground">Analytics and performance metrics</p>
        </div>
        
        <div className="flex items-center gap-2">
          <Select value={selectedPreset} onValueChange={(v) => handlePresetChange(v as any)}>
            <SelectTrigger className="w-[160px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {PRESET_RANGES.map(range => (
                <SelectItem key={range.value} value={range.value}>{range.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="outline" size="icon"><CalendarIcon className="h-4 w-4" /></Button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="end">
              <Calendar
                mode="range"
                selected={{ from: dateRange.from, to: dateRange.to }}
                onSelect={(range) => range?.from && range?.to && setCustomRange({ from: range.from, to: range.to })}
                numberOfMonths={2}
              />
            </PopoverContent>
          </Popover>
        </div>
      </div>

      <div className="text-sm text-muted-foreground">
        Showing data from {format(dateRange.from, 'MMM d, yyyy')} to {format(dateRange.to, 'MMM d, yyyy')}
      </div>

      {isLoading ? (
        <div className="space-y-6">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {[1, 2, 3, 4].map(i => <Skeleton key={i} className="h-[120px] rounded-xl" />)}
          </div>
          <Skeleton className="h-[400px] rounded-xl" />
        </div>
      ) : error ? (
        <Card className="p-8">
          <div className="text-center space-y-3">
            <AlertTriangle className="h-12 w-12 text-destructive mx-auto" />
            <h3 className="text-lg font-semibold">Failed to Load Reports</h3>
            <p className="text-muted-foreground">{error}</p>
            <Button onClick={() => loadMetrics(dateRange)} variant="outline">
              Try Again
            </Button>
          </div>
        </Card>
      ) : hasNoData ? (
        <Card className="p-8">
          <div className="text-center space-y-3">
            <Users className="h-12 w-12 text-muted-foreground mx-auto" />
            <h3 className="text-lg font-semibold">No Data Available</h3>
            <p className="text-muted-foreground">
              No reports data found for the selected date range. Start by scheduling appointments and recording treatments.
            </p>
          </div>
        </Card>
      ) : metrics ? (
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList>
            <TabsTrigger value="overview">Overview</TabsTrigger>
            <TabsTrigger value="appointments">Appointments</TabsTrigger>
            <TabsTrigger value="revenue">Revenue</TabsTrigger>
            <TabsTrigger value="utilization">Utilization</TabsTrigger>
          </TabsList>

          <TabsContent value="overview" className="space-y-6">
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <MetricCard title="Total Appointments" value={metrics.appointments.total} subtitle={`${metrics.appointments.completionRate}% completion rate`} icon={Users} />
              <MetricCard title="Revenue" value={formatCurrency(metrics.revenue.totalRevenue)} subtitle={`${formatCurrency(metrics.revenue.averagePerVisit)} avg/visit`} icon={DollarSign} />
              <MetricCard title="Treatment Acceptance" value={`${metrics.treatmentAcceptance.acceptanceRate}%`} subtitle={`${metrics.treatmentAcceptance.acceptedPlans} of ${metrics.treatmentAcceptance.proposedPlans} plans`} icon={TrendingUp} />
              <MetricCard title="Chair Utilization" value={`${metrics.chairUtilization.averageUtilization}%`} subtitle={`${metrics.chairUtilization.totalChairs} chairs`} icon={Clock} />
            </div>

            <div className="grid gap-4 sm:grid-cols-3">
              {[
                { label: 'No-Show Rate', value: `${metrics.appointments.noShowRate}%`, icon: AlertTriangle, bg: 'bg-red-100', text: 'text-red-600' },
                { label: 'Collected', value: formatCurrency(metrics.revenue.totalCollected), icon: CheckCircle2, bg: 'bg-green-100', text: 'text-green-600' },
                { label: 'Outstanding', value: formatCurrency(metrics.revenue.totalOutstanding), icon: XCircle, bg: 'bg-amber-100', text: 'text-amber-600' }
              ].map((m, i) => (
                <Card key={i}>
                  <CardContent className="pt-6">
                    <div className="flex items-center gap-3">
                      <div className={cn("flex h-10 w-10 items-center justify-center rounded-lg", m.bg)}>
                        <m.icon className={cn("h-5 w-5", m.text)} />
                      </div>
                      <div>
                        <p className="text-2xl font-bold">{m.value}</p>
                        <p className="text-sm text-muted-foreground">{m.label}</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            <div className="grid gap-6 lg:grid-cols-2">
              <RevenueChart data={metrics.revenue.byMonth} formatCurrency={formatCurrency} />
              <AppointmentPieChart data={metrics.appointments.byType} colors={COLORS} />
            </div>
          </TabsContent>

          <TabsContent value="appointments" className="space-y-6">
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => handleExport('appointments')}><Download className="h-4 w-4 mr-2" />Export</Button>
            </div>
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <MetricCard title="Total" value={metrics.appointments.total} icon={Users} />
              <MetricCard title="Completed" value={metrics.appointments.completed} icon={CheckCircle2} />
              <MetricCard title="Cancelled" value={metrics.appointments.cancelled} icon={XCircle} />
              <MetricCard title="No-Shows" value={metrics.appointments.noShow} icon={AlertTriangle} />
            </div>
            <div className="grid gap-6 lg:grid-cols-2">
              <DailyAppointmentsChart data={metrics.appointments.byDay} />
              <Card>
                <CardHeader><CardTitle>Appointment Types</CardTitle></CardHeader>
                <CardContent className="space-y-3">
                  {metrics.appointments.byType.map((type, index) => (
                    <div key={type.type} className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }} />
                        <span className="text-sm">{type.type}</span>
                      </div>
                      <span className="font-medium">{type.count}</span>
                    </div>
                  ))}
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          <TabsContent value="revenue" className="space-y-6">
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => handleExport('revenue')}><Download className="h-4 w-4 mr-2" />Export</Button>
            </div>
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <MetricCard title="Total Revenue" value={formatCurrency(metrics.revenue.totalRevenue)} icon={DollarSign} />
              <MetricCard title="Collected" value={formatCurrency(metrics.revenue.totalCollected)} icon={CheckCircle2} />
              <MetricCard title="Outstanding" value={formatCurrency(metrics.revenue.totalOutstanding)} icon={Clock} />
              <MetricCard title="Avg per Visit" value={formatCurrency(metrics.revenue.averagePerVisit)} icon={TrendingUp} />
            </div>
            <div className="grid gap-6 lg:grid-cols-2">
              <MonthlyRevenueChart data={metrics.revenue.byMonth} formatCurrency={formatCurrency} />
              <Card>
                <CardHeader><CardTitle>Revenue by Procedure</CardTitle></CardHeader>
                <CardContent className="space-y-3">
                  {metrics.revenue.byProcedure.length > 0 ? (
                    metrics.revenue.byProcedure.map((proc, index) => {
                      const maxRevenue = Math.max(...metrics.revenue.byProcedure.map(p => p.revenue));
                      return (
                        <div key={proc.procedure} className="space-y-1">
                          <div className="flex items-center justify-between text-sm">
                            <span>{proc.procedure}</span>
                            <span className="font-medium">{formatCurrency(proc.revenue)}</span>
                          </div>
                          <div className="h-2 bg-muted rounded-full overflow-hidden">
                            <div className="h-full rounded-full transition-all" style={{ width: `${(proc.revenue / maxRevenue) * 100}%`, backgroundColor: COLORS[index % COLORS.length] }} />
                          </div>
                        </div>
                      );
                    })
                  ) : (
                    <p className="text-sm text-muted-foreground text-center py-4">No procedure data available</p>
                  )}
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          <TabsContent value="utilization" className="space-y-6">
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => handleExport('utilization')}><Download className="h-4 w-4 mr-2" />Export</Button>
            </div>
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              <MetricCard title="Average Utilization" value={`${metrics.chairUtilization.averageUtilization}%`} icon={Clock} />
              <MetricCard title="Total Chairs" value={metrics.chairUtilization.totalChairs} icon={Users} />
              <MetricCard 
                title="Peak Hour" 
                value={metrics.chairUtilization.peakHours.length > 0 ? metrics.chairUtilization.peakHours.reduce((max, h) => h.utilization > max.utilization ? h : max).hour : 'N/A'} 
                subtitle={metrics.chairUtilization.peakHours.length > 0 ? `${metrics.chairUtilization.peakHours.reduce((max, h) => h.utilization > max.utilization ? h : max).utilization}% utilization` : 'No data'}
                icon={TrendingUp} 
              />
            </div>
            <UtilizationCharts 
              peakHours={metrics.chairUtilization.peakHours} 
              byChair={metrics.chairUtilization.byChair} 
              byDayOfWeek={metrics.chairUtilization.byDayOfWeek} 
            />
          </TabsContent>
        </Tabs>
      ) : null}
    </div>
  );
}

// ============================================
// CoreDent PMS - Reset Password Page
// UI for setting new password (token validated by external API)
// ============================================

import React, { useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Stethoscope, Eye, EyeOff, Loader2, CheckCircle, Lock } from 'lucide-react';
import { z } from 'zod';
import { useToast } from '@/hooks/use-toast';
import { authApi } from '@/services/api';

const passwordSchema = z.object({
  password: z.string()
    .min(8, 'Password must be at least 8 characters')
    .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
    .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
    .regex(/[0-9]/, 'Password must contain at least one number'),
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

export default function ResetPassword() {
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token');

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState<{ password?: string; confirmPassword?: string }>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const { toast } = useToast();

  // Password strength indicator
  const getPasswordStrength = (pwd: string) => {
    let strength = 0;
    if (pwd.length >= 8) strength++;
    if (/[A-Z]/.test(pwd)) strength++;
    if (/[a-z]/.test(pwd)) strength++;
    if (/[0-9]/.test(pwd)) strength++;
    if (/[^A-Za-z0-9]/.test(pwd)) strength++;
    return strength;
  };

  const strength = getPasswordStrength(password);
  const strengthLabels = ['Very Weak', 'Weak', 'Fair', 'Good', 'Strong'];
  const strengthColors = ['bg-destructive', 'bg-orange-500', 'bg-yellow-500', 'bg-blue-500', 'bg-green-500'];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrors({});

    // Validate input
    const result = passwordSchema.safeParse({ password, confirmPassword });

    if (!result.success) {
      const fieldErrors: { password?: string; confirmPassword?: string } = {};
      result.error.issues.forEach((issue) => {
        const field = issue.path[0] as 'password' | 'confirmPassword';
        fieldErrors[field] = issue.message;
      });
      setErrors(fieldErrors);
      return;
    }

    if (!token) {
      toast({
        variant: 'destructive',
        title: 'Invalid Link',
        description: 'This password reset link is invalid or has expired.',
      });
      return;
    }

    setIsSubmitting(true);

    try {
      const response = await authApi.resetPassword({ token, password });
      if (!response.success) {
        throw new Error(response.error?.message || 'Unable to reset password');
      }
      setIsSuccess(true);
      toast({
        title: 'Password Updated',
        description: 'Your password has been successfully reset.',
      });
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Unable to reset password. The link may have expired.',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!token) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-muted/30 p-4">
        <div className="w-full max-w-md">
          <Card className="shadow-lg">
            <CardContent className="pt-6">
              <div className="flex flex-col items-center text-center space-y-4">
                <div className="flex h-16 w-16 items-center justify-center rounded-full bg-destructive/10">
                  <Lock className="h-8 w-8 text-destructive" />
                </div>
                <h2 className="text-2xl font-semibold">Invalid Link</h2>
                <p className="text-muted-foreground">
                  This password reset link is invalid or has expired.
                </p>
              </div>
            </CardContent>
            <CardFooter>
              <Link to="/forgot-password" className="w-full">
                <Button className="w-full">Request New Link</Button>
              </Link>
            </CardFooter>
          </Card>
        </div>
      </div>
    );
  }

  if (isSuccess) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-muted/30 p-4">
        <div className="w-full max-w-md">
          <div className="flex flex-col items-center mb-8">
            <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-primary mb-4">
              <Stethoscope className="h-8 w-8 text-primary-foreground" />
            </div>
            <h1 className="text-3xl font-bold">CoreDent</h1>
          </div>

          <Card className="shadow-lg">
            <CardContent className="pt-6">
              <div className="flex flex-col items-center text-center space-y-4">
                <div className="flex h-16 w-16 items-center justify-center rounded-full bg-green-100 dark:bg-green-900">
                  <CheckCircle className="h-8 w-8 text-green-600 dark:text-green-400" />
                </div>
                <h2 className="text-2xl font-semibold">Password Reset Complete</h2>
                <p className="text-muted-foreground">
                  Your password has been successfully updated. You can now sign in with your new password.
                </p>
              </div>
            </CardContent>
            <CardFooter>
              <Link to="/login" className="w-full">
                <Button className="w-full" size="lg">
                  Sign In
                </Button>
              </Link>
            </CardFooter>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-muted/30 p-4">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="flex flex-col items-center mb-8">
          <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-primary mb-4">
            <Stethoscope className="h-8 w-8 text-primary-foreground" />
          </div>
          <h1 className="text-3xl font-bold">CoreDent</h1>
          <p className="text-muted-foreground">Dental Practice Management</p>
        </div>

        {/* Reset Card */}
        <Card className="shadow-lg">
          <CardHeader className="space-y-1">
            <CardTitle className="text-2xl text-center">Set New Password</CardTitle>
            <CardDescription className="text-center">
              Create a strong password for your account
            </CardDescription>
          </CardHeader>

          <form onSubmit={handleSubmit}>
            <CardContent className="space-y-4">
              {/* New Password Field */}
              <div className="space-y-2">
                <Label htmlFor="password">New Password</Label>
                <div className="relative">
                  <Input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className={errors.password ? 'border-destructive pr-10' : 'pr-10'}
                    disabled={isSubmitting}
                    autoComplete="new-password"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="absolute right-0 top-0 h-full px-3 hover:bg-transparent"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? (
                      <EyeOff className="h-4 w-4 text-muted-foreground" />
                    ) : (
                      <Eye className="h-4 w-4 text-muted-foreground" />
                    )}
                  </Button>
                </div>
                {errors.password && (
                  <p className="text-sm text-destructive">{errors.password}</p>
                )}

                {/* Password Strength Indicator */}
                {password && (
                  <div className="space-y-2">
                    <div className="flex gap-1">
                      {[1, 2, 3, 4, 5].map((level) => (
                        <div
                          key={level}
                          className={`h-1 flex-1 rounded-full transition-colors ${
                            strength >= level ? strengthColors[strength - 1] : 'bg-muted'
                          }`}
                        />
                      ))}
                    </div>
                    <p className="text-xs text-muted-foreground">
                      Strength: {strength > 0 ? strengthLabels[strength - 1] : 'Too weak'}
                    </p>
                  </div>
                )}
              </div>

              {/* Confirm Password Field */}
              <div className="space-y-2">
                <Label htmlFor="confirmPassword">Confirm Password</Label>
                <Input
                  id="confirmPassword"
                  type={showPassword ? 'text' : 'password'}
                  placeholder="••••••••"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className={errors.confirmPassword ? 'border-destructive' : ''}
                  disabled={isSubmitting}
                  autoComplete="new-password"
                />
                {errors.confirmPassword && (
                  <p className="text-sm text-destructive">{errors.confirmPassword}</p>
                )}
              </div>

              {/* Password Requirements */}
              <div className="text-xs text-muted-foreground space-y-1">
                <p>Password must contain:</p>
                <ul className="list-disc list-inside space-y-0.5">
                  <li className={password.length >= 8 ? 'text-green-600' : ''}>At least 8 characters</li>
                  <li className={/[A-Z]/.test(password) ? 'text-green-600' : ''}>One uppercase letter</li>
                  <li className={/[a-z]/.test(password) ? 'text-green-600' : ''}>One lowercase letter</li>
                  <li className={/[0-9]/.test(password) ? 'text-green-600' : ''}>One number</li>
                </ul>
              </div>
            </CardContent>

            <CardFooter>
              <Button 
                type="submit" 
                className="w-full" 
                size="lg"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Updating...
                  </>
                ) : (
                  'Update Password'
                )}
              </Button>
            </CardFooter>
          </form>
        </Card>

        {/* Footer */}
        <p className="text-center text-sm text-muted-foreground mt-6">
          © 2025 CoreDent PMS. All rights reserved.
        </p>
      </div>
    </div>
  );
}

// ============================================
// Schedule Page
// Main appointment scheduling interface
// ============================================

import { useEffect, useState, useCallback } from 'react';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/contexts/auth-context';
import { ScheduleHeader } from '@/components/scheduling/ScheduleHeader';
import { DayView } from '@/components/scheduling/DayView';
import { WeekView } from '@/components/scheduling/WeekView';
import { MonthView } from '@/components/scheduling/MonthView';
import { AppointmentDialog } from '@/components/scheduling/AppointmentDialog';
import { AppointmentDetailsSheet } from '@/components/scheduling/AppointmentDetailsSheet';
import { PatientSearchDialog } from '@/components/scheduling/PatientSearchDialog';
import { useScheduling } from '@/hooks/useScheduling';
import { schedulingApi } from '@/services/schedulingApi';
import { triggerAutomation } from '@/services/automationApi';
import type { ScheduleAppointment, AppointmentFormData, PatientSearchResult } from '@/types/scheduling';
import type { AppointmentStatus } from '@/types/api';
import { parseTimeString } from '@/types/scheduling';
import { Skeleton } from '@/components/ui/skeleton';

export default function Schedule() {
  const { toast } = useToast();
  const { hasRole } = useAuth();
  
  // Check if user can edit appointments
  const canEdit = hasRole('owner', 'admin', 'front_desk');

  const {
    currentDate,
    view,
    appointments,
    chairs,
    providers,
    appointmentTypes,
    isLoading,
    selectedAppointment,
    formattedDate,
    setView,
    setSelectedAppointment,
    goToToday,
    goToPrevious,
    goToNext,
    goToDate,
    loadData,
    addAppointment,
    updateAppointment,
    removeAppointment,
  } = useScheduling();

  // Dialog states
  const [isAppointmentDialogOpen, setIsAppointmentDialogOpen] = useState(false);
  const [isDetailsSheetOpen, setIsDetailsSheetOpen] = useState(false);
  const [isPatientSearchOpen, setIsPatientSearchOpen] = useState(false);
  const [editingAppointment, setEditingAppointment] = useState<ScheduleAppointment | null>(null);
  const [selectedPatientForNew, setSelectedPatientForNew] = useState<PatientSearchResult | null>(null);

  // effect:audited — Load data on mount and when date changes
  useEffect(() => {
    loadData();
  }, [loadData]);

  // Handle appointment click - show details
  const handleAppointmentClick = useCallback((appointment: ScheduleAppointment) => {
    setSelectedAppointment(appointment);
    setIsDetailsSheetOpen(true);
  }, [setSelectedAppointment]);

  // Handle status change
  const handleStatusChange = useCallback(async (id: string, status: AppointmentStatus) => {
    try {
      await schedulingApi.updateStatus(id, status);
      updateAppointment(id, { status });
      toast({
        title: 'Status Updated',
        description: `Appointment marked as ${status.replace('_', ' ')}`,
      });

      // Trigger automation for status changes
      const appointment = appointments.find(a => a.id === id);
      if (appointment) {
        const payload = {
          appointmentId: id,
          patientName: appointment.patientName,
          appointmentDate: appointment.startTime.toISOString().split('T')[0],
          appointmentTime: appointment.startTime.toLocaleTimeString(),
          providerName: appointment.providerName || '',
          procedureType: appointment.type,
          clinicName: 'CoreDent Clinic',
        };
        if (status === 'confirmed') triggerAutomation('appointment_confirmed', payload);
        if (status === 'completed') {
          triggerAutomation('appointment_completed', payload);
          triggerAutomation('review_request', {
            patientId: appointment.patientId,
            patientName: appointment.patientName,
            appointmentDate: payload.appointmentDate,
            providerName: payload.providerName,
            clinicName: 'CoreDent Clinic',
          });
        }
        if (status === 'no_show') triggerAutomation('appointment_no_show', payload);
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update appointment status',
        variant: 'destructive',
      });
    }
  }, [appointments, updateAppointment, toast]);

  // Handle edit appointment
  const handleEditAppointment = useCallback((appointment: ScheduleAppointment) => {
    setEditingAppointment(appointment);
    setIsDetailsSheetOpen(false);
    setIsAppointmentDialogOpen(true);
  }, []);

  // Handle cancel appointment
  const handleCancelAppointment = useCallback(async (id: string) => {
    try {
      await schedulingApi.cancelAppointment(id);
      updateAppointment(id, { status: 'cancelled' });
      setIsDetailsSheetOpen(false);
      toast({
        title: 'Appointment Cancelled',
        description: 'The appointment has been cancelled',
      });

      // Trigger appointment_cancelled automation
      const appointment = appointments.find(a => a.id === id);
      if (appointment) {
        triggerAutomation('appointment_cancelled', {
          appointmentId: id,
          patientName: appointment.patientName,
          appointmentDate: appointment.startTime.toISOString().split('T')[0],
          appointmentTime: appointment.startTime.toLocaleTimeString(),
          providerName: appointment.providerName || '',
          procedureType: appointment.type,
          clinicName: 'CoreDent Clinic',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to cancel appointment',
        variant: 'destructive',
      });
    }
  }, [appointments, updateAppointment, toast]);

  // Handle new appointment
  const handleNewAppointment = useCallback(() => {
    setEditingAppointment(null);
    setSelectedPatientForNew(null);
    setIsAppointmentDialogOpen(true);
  }, []);

  // Handle save appointment
  const handleSaveAppointment = useCallback(async (data: AppointmentFormData) => {
    if (editingAppointment) {
      await schedulingApi.updateAppointment(editingAppointment.id, data);
      const { hours, minutes } = parseTimeString(data.startTime);
      const startTime = new Date(data.date);
      startTime.setHours(hours, minutes, 0, 0);
      const endTime = new Date(startTime.getTime() + data.duration * 60 * 1000);
      
      updateAppointment(editingAppointment.id, {
        patientId: data.patientId,
        patientName: data.patientName,
        providerId: data.providerId,
        chairId: data.chairId,
        type: data.type,
        startTime,
        endTime,
        duration: data.duration,
        notes: data.notes,
      });
      toast({
        title: 'Appointment Updated',
        description: 'The appointment has been updated successfully',
      });
      return;
    }

    const newAppointment = await schedulingApi.createAppointment(data);
    addAppointment(newAppointment);
    toast({
      title: 'Appointment Created',
      description: `Appointment scheduled for ${data.patientName}`,
    });

    triggerAutomation('appointment_booked', {
      appointmentId: newAppointment.id,
      patientName: data.patientName,
      appointmentDate: data.date.toISOString().split('T')[0],
      appointmentTime: data.startTime,
      providerName: newAppointment.providerName || '',
      procedureType: data.type,
      clinicName: 'CoreDent Clinic',
    });
  }, [editingAppointment, updateAppointment, addAppointment, toast]);

  // Handle drag-and-drop reschedule (Day View)
  const handleDropAppointmentDay = useCallback(async (appointmentId: string, chairId: string, time: string) => {
    try {
      const appointment = appointments.find(a => a.id === appointmentId);
      if (!appointment) return;

      const { hours, minutes } = parseTimeString(time);
      const newStartTime = new Date(currentDate);
      newStartTime.setHours(hours, minutes, 0, 0);
      const newEndTime = new Date(newStartTime.getTime() + appointment.duration * 60 * 1000);

      await schedulingApi.rescheduleAppointment(appointmentId, chairId, newStartTime);
      
      const chair = chairs.find(c => c.id === chairId);
      updateAppointment(appointmentId, {
        chairId,
        chairName: chair?.name || '',
        startTime: newStartTime,
        endTime: newEndTime,
      });

      toast({
        title: 'Appointment Rescheduled',
        description: `Moved to ${chair?.name || 'new location'}`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to reschedule appointment',
        variant: 'destructive',
      });
    }
  }, [appointments, currentDate, chairs, updateAppointment, toast]);

  // Handle drag-and-drop reschedule (Week View)
  const handleDropAppointmentWeek = useCallback(async (appointmentId: string, date: Date, time: string) => {
    try {
      const appointment = appointments.find(a => a.id === appointmentId);
      if (!appointment) return;

      const { hours, minutes } = parseTimeString(time);
      const newStartTime = new Date(date);
      newStartTime.setHours(hours, minutes, 0, 0);
      const newEndTime = new Date(newStartTime.getTime() + appointment.duration * 60 * 1000);

      await schedulingApi.rescheduleAppointment(appointmentId, appointment.chairId, newStartTime);
      
      updateAppointment(appointmentId, {
        startTime: newStartTime,
        endTime: newEndTime,
      });

      toast({
        title: 'Appointment Rescheduled',
        description: 'Appointment moved successfully',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to reschedule appointment',
        variant: 'destructive',
      });
    }
  }, [appointments, updateAppointment, toast]);

  // Handle day click from week/month view
  const handleDayClick = useCallback((date: Date) => {
    goToDate(date);
    setView('day');
  }, [goToDate, setView]);

  // Handle patient select from search
  const handlePatientSelect = useCallback((patient: PatientSearchResult) => {
    setSelectedPatientForNew(patient);
    setIsPatientSearchOpen(false);
    setIsAppointmentDialogOpen(true);
  }, []);

  if (isLoading && appointments.length === 0) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-20 w-full" />
        <Skeleton className="h-[600px] w-full" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-8rem)]">
      <ScheduleHeader
        formattedDate={formattedDate}
        currentDate={currentDate}
        view={view}
        onViewChange={setView}
        onPrevious={goToPrevious}
        onNext={goToNext}
        onToday={goToToday}
        onDateSelect={goToDate}
        onNewAppointment={handleNewAppointment}
        onOpenSearch={() => setIsPatientSearchOpen(true)}
      />

      <div className="flex-1 mt-4 overflow-hidden border rounded-lg bg-card">
        {view === 'day' && (
          <DayView
            date={currentDate}
            chairs={chairs}
            appointments={appointments}
            onAppointmentClick={handleAppointmentClick}
            onStatusChange={handleStatusChange}
            onEditAppointment={handleEditAppointment}
            onCancelAppointment={handleCancelAppointment}
            onDropAppointment={handleDropAppointmentDay}
            canEdit={canEdit}
          />
        )}

        {view === 'week' && (
          <WeekView
            currentDate={currentDate}
            appointments={appointments}
            onAppointmentClick={handleAppointmentClick}
            onStatusChange={handleStatusChange}
            onEditAppointment={handleEditAppointment}
            onCancelAppointment={handleCancelAppointment}
            onDropAppointment={handleDropAppointmentWeek}
            onDayClick={handleDayClick}
            canEdit={canEdit}
          />
        )}

        {view === 'month' && (
          <MonthView
            currentDate={currentDate}
            appointments={appointments}
            onDayClick={handleDayClick}
            onAppointmentClick={handleAppointmentClick}
          />
        )}
      </div>

      {/* Appointment Create/Edit Dialog */}
      <AppointmentDialog
        open={isAppointmentDialogOpen}
        onOpenChange={setIsAppointmentDialogOpen}
        appointment={editingAppointment}
        chairs={chairs}
        providers={providers}
        appointmentTypes={appointmentTypes}
        defaultDate={currentDate}
        onSave={handleSaveAppointment}
      />

      {/* Appointment Details Sheet */}
      <AppointmentDetailsSheet
        open={isDetailsSheetOpen}
        onOpenChange={setIsDetailsSheetOpen}
        appointment={selectedAppointment}
        onEdit={() => selectedAppointment && handleEditAppointment(selectedAppointment)}
        onStatusChange={(status: AppointmentStatus) => selectedAppointment && handleStatusChange(selectedAppointment.id, status)}
        onCancel={() => selectedAppointment && handleCancelAppointment(selectedAppointment.id)}
        canEdit={canEdit}
      />

      {/* Patient Search Dialog */}
      <PatientSearchDialog
        open={isPatientSearchOpen}
        onOpenChange={setIsPatientSearchOpen}
        onSelectPatient={handlePatientSelect}
      />
    </div>
  );
}

